15:     public function toArray(Request $request): array
16:     {
17:         return [
18:             'id' => $this->id,
19:             'name' => $this->name,
20:             'email' => $this->email,
21:             'phone' => $this->phone,
22:             'branch_id' => $this->branch_id,
23:             'branch' => $this->whenLoaded('branch', fn (): ?array => $this->branch === null
24:                 ? null
25:                 : ['id' => $this->branch->id, 'name' => $this->branch->name]),
26:             'is_active' => $this->is_active,
27:             'roles' => $this->whenLoaded(
28:                 'roles',
29:                 fn () => $this->roles->map(fn ($role): array => [
30:                     'id' => $role->id,
31:                     'name' => $role->name,
32:                 ])->values(),
33:             ),
34:             'permissions' => $this->when(
35:                 $this->relationLoaded('roles')
36:                     && $this->relationLoaded('permissions')
37:                     && $this->roles->every(fn ($role): bool => $role->relationLoaded('permissions')),
38:                 fn () => $this->getAllPermissions()->pluck('name')->unique()->values(),
39:             ),
40:             'created_at' => $this->created_at,
41:             'updated_at' => $this->updated_at,
42:         ];
43:     }
44: } 1: <?php
