21:     public function up(): void
22:     {
23:         DB::statement("SET lock_timeout = '2s'");
24:         try {
25:             foreach (['users', 'supplier_users'] as $table) {
26:                 $duplicate = DB::table($table)
27:                     ->selectRaw('LOWER(TRIM(email)) AS normalized')
28:                     ->groupByRaw('LOWER(TRIM(email))')
29:                     ->havingRaw('COUNT(*) > 1')
30:                     ->exists();
31:                 if ($duplicate) {
32:                     throw new RuntimeException("Resolve duplicate {$table}.email values (case-insensitive) before adding the unique index.");
33:                 }
34:                 DB::statement("UPDATE {$table} SET email = LOWER(TRIM(email)) WHERE email <> LOWER(TRIM(email))");
35:             }
36: 
37:             $this->dropInvalidIndex('users_email_ci_unique');
38:             DB::statement('CREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS users_email_ci_unique ON users (LOWER(email))');
39:             $this->dropInvalidIndex('supplier_users_email_ci_unique');
40:             DB::statement('CREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS supplier_users_email_ci_unique ON supplier_users (LOWER(email))');
41:         } finally {
42:             DB::statement('RESET lock_timeout');
43:         }
44:     }
45: 
46:     public function down(): void
