  5: namespace Tests\Feature\Auth;
  6: 
  7: use App\Enums\CustomerStatus;
  8: use App\Models\Branch;
  9: use App\Models\Customer;
 10: use App\Models\Supplier;
 11: use App\Models\SupplierUser;
 12: use App\Models\User;
 13: use App\Rules\EmailNotUsedByOtherAccountType;
 14: use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
 15: use Illuminate\Support\Facades\Auth;
 16: use Spatie\Permission\Models\Role;
 17: use Tests\TestCase;
 18: 
 19: class UnifiedLoginHardeningTest extends TestCase
 20: {
 21:     use LazilyRefreshDatabase;
 22: 
 23:     public function test_supplier_login_rejected_when_company_inactive(): void
 24:     {
 25:         $supplier = Supplier::factory()->create(['is_active' => false]);
 26:         $user = SupplierUser::factory()->create(['supplier_id' => $supplier->id, 'password' => 'sup-pass']);
 27: 
 28:         $this->login(['login' => $user->email, 'password' => 'sup-pass'])
 29:             ->assertUnauthorized()
 30:             ->assertJsonPath('message', 'بيانات الدخول غير صحيحة.');
 31: 
 32:         $this->assertSame(0, $user->tokens()->count());
 33:     }
 34: 
 35:     public function test_me_returns_destination_subtype_with_separate_customer_type(): void
 36:     {
 37:         $customer = Customer::factory()->wholesale()->create(['password' => 'cust-pass']);
 38:         $token = (string) $this->login(['login' => $customer->phone, 'password' => 'cust-pass'])->json('token');
 39: 
 40:         $this->authed('get', '/api/v1/auth/me', $token)
 41:             ->assertOk()
 42:             ->assertJsonPath('actor.type', 'customer')
 43:             ->assertJsonPath('actor.subtype', 'wholesale_pending')
 44:             ->assertJsonPath('actor.customer_type', 'wholesale');
 45:     }
 46: 
 47:     public function test_array_login_returns_validation_error_not_server_error(): void
 48:     {
 49:         $this->login(['login' => ['01012345678'], 'password' => 'x'])
 50:             ->assertStatus(422);
 51:     }
 52: 
 53:     public function test_phone_format_variants_share_one_rate_limit_bucket(): void
 54:     {
 55:         foreach (['01012345678', '010 1234 5678', '+201012345678', '00201012345678'] as $variant) {
 56:             $this->login(['login' => $variant, 'password' => 'wrong']);
 57:         }
 58:         // الخامسة مسموحة (5/دقيقة)، والسادسة بصيغة مختلفة كانت قبل الإصلاح
 59:         // بعدّاد مستقل فتفلت — الآن تُحجب.
 60:         $this->login(['login' => '01012345678', 'password' => 'wrong'])->assertUnauthorized();
 61:         $this->login(['login' => '+201012345678', 'password' => 'wrong'])->assertStatus(429);
 62:     }
 63: 
 64:     public function test_cashier_with_inactive_branch_is_forbidden(): void
 65:     {
 66:         $branch = Branch::factory()->create(['is_active' => false]);
 67:         $cashier = User::factory()->create(['is_active' => true, 'branch_id' => $branch->id]);
 68:         $cashier->assignRole(Role::firstOrCreate(['name' => 'cashier', 'guard_name' => 'staff']));
 69: 
 70:         $this->login(['login' => $cashier->email, 'password' => 'password'])
 71:             ->assertForbidden();
 72:     }
 73: 
 74:     public function test_customer_login_reports_cart_merge_result(): void
 75:     {
 76:         $customer = Customer::factory()->create(['password' => 'cust-pass']);
 77: 
 78:         $this->login(['login' => $customer->phone, 'password' => 'cust-pass'])
 79:             ->assertOk()
 80:             ->assertJsonPath('cart_merged', true);
 81:     }
 82: 
 83:     public function test_supplier_tokens_are_capped(): void
 84:     {
 85:         config()->set('auth.supplier_max_tokens', 2);
 86:         $user = SupplierUser::factory()->create(['password' => 'sup-pass']);
 87: 
 88:         for ($i = 0; $i < 3; $i++) {
 89:             $this->login(['login' => $user->email, 'password' => 'sup-pass'])->assertOk();
 90:         }
 91: 
 92:         $this->assertSame(2, $user->tokens()->count());
 93:     }
 94: 
 95:     public function test_rejected_retail_customer_goes_to_application_status(): void
 96:     {
 97:         $customer = Customer::factory()->create([
 98:             'password' => 'cust-pass', 'status' => CustomerStatus::Rejected,
 99:             'rejection_reason' => 'بيانات ناقصة',
100:         ]);
101: 
102:         $response = $this->login(['login' => $customer->phone, 'password' => 'cust-pass']);
103:         $response->assertOk()
104:             ->assertJsonPath('redirect.path', '/wholesale/application-status')
105:             ->assertJsonPath('actor.subtype', 'wholesale_pending');
106: 
107:         $this->authed('get', '/api/v1/wholesale/auth/application-status', (string) $response->json('token'))
108:             ->assertOk()
109:             ->assertJsonPath('data.rejection_reason', 'بيانات ناقصة');
110:     }
111: 
112:     public function test_unverified_customer_email_does_not_block_other_account_types(): void
113:     {
114:         Customer::factory()->create(['email' => 'pending-cust@example.test', 'email_verified_at' => null]);
115: 
116:         $failed = false;
