  5: namespace App\Http\Controllers\Api\V1\Auth;
  6: 
  7: use App\Enums\CustomerStatus;
  8: use App\Enums\CustomerType;
  9: use App\Exceptions\BusinessException;
 10: use App\Http\Controllers\Controller;
 11: use App\Http\Requests\Api\V1\Auth\HandoffExchangeRequest;
 12: use App\Http\Requests\Api\V1\Auth\UnifiedLoginRequest;
 13: use App\Http\Resources\Api\V1\Admin\UserResource;
 14: use App\Http\Resources\Api\V1\Supplier\SupplierUserResource;
 15: use App\Http\Resources\Store\CustomerResource;
 16: use App\Models\Customer;
 17: use App\Models\SupplierUser;
 18: use App\Models\User;
 19: use App\Services\Auth\LoginDestinationResolver;
 20: use App\Services\Auth\StaffHandoffService;
 21: use App\Services\Auth\UnifiedAuthService;
 22: use App\Services\CartService;
 23: use App\Services\CustomerAuthService;
 24: use Illuminate\Http\JsonResponse;
 25: use Illuminate\Http\Request;
 26: use Illuminate\Http\Response;
 27: use Illuminate\Support\Facades\DB;
 28: 
 29: class UnifiedAuthController extends Controller
 30: {
 31:     public function __construct(
 32:         private readonly UnifiedAuthService $auth,
 33:         private readonly LoginDestinationResolver $destinations,
 34:         private readonly StaffHandoffService $handoff,
 35:         private readonly CustomerAuthService $customerAuth,
 36:         private readonly CartService $carts,
 37:     ) {}
 38: 
 39:     public function login(UnifiedLoginRequest $request): JsonResponse
 40:     {
 41:         $data = $request->validated();
 42:         $actor = $this->auth->attempt($data['login'], $data['password']);
 43:         $redirect = $this->destinations->resolve($actor, $data['redirect'] ?? null);
 44: 
 45:         if ($actor instanceof User) {
 46:             return $this->respond('staff', $redirect, null, $this->handoff->issue($actor, $redirect['path']),
 47:                 ['id' => $actor->id, 'name' => $actor->name], 'active');
 48:         }
 49: 
 50:         if ($actor instanceof SupplierUser) {
 51:             $actor->load('supplier');
 52: 
 53:             return $this->respond('supplier', $redirect, $this->issueSupplierToken($actor), null,
 54:                 SupplierUserResource::make($actor)->resolve($request), 'active');
 55:         }
 56: 
 57:         /** @var Customer $actor */
 58:         $token = $this->customerAuth->issueToken($actor, $actor->type === CustomerType::Retail ? 'store-token' : 'wholesale-token');
 59:         // M10: الدمج best-effort بعد إصدار التوكن — فشله لا يُفشل الدخول ولا
 60:         // يُيتّم التوكن؛ يُبلغ الفرونت بالنتيجة ليحتفظ بـ cart_session عند الفشل.
 61:         $cartMerged = true;
 62:         try {
 63:             $this->carts->mergeGuestCart($actor, $request->header('X-Cart-Session'));
 64:         } catch (\Throwable $exception) {
 65:             report($exception);
 66:             $cartMerged = false;
 67:         }
 68: 
 69:         return $this->respond('customer', $redirect, $token, null,
 70:             CustomerResource::make($actor)->resolve($request), $actor->status->value,
 71:             $actor->type->value, $cartMerged);
 72:     }
 73: 
 74:     public function exchange(HandoffExchangeRequest $request): JsonResponse
 75:     {
 76:         // M8: القفل قد يرمي LockTimeoutException تحت التزامن — تُعامل ككود
 77:         // غير صالح (401) بدل 500.
 78:         try {
 79:             $payload = $this->handoff->consume($request->validated()['code']);
 80:         } catch (\Throwable $exception) {
 81:             report($exception);
 82:             $payload = null;
 83:         }
 84:         $user = $payload ? User::query()->find($payload['user_id']) : null;
 85: 
 86:         if (! $user instanceof User || ! $user->is_active) {
 87:             logger()->info('staff.handoff', ['result' => 'rejected']);
 88: 
 89:             return response()->json(['message' => 'رابط الدخول غير صالح أو انتهت صلاحيته.'], 401);
 90:         }
 91: 
 92:         // تُحسم الوجهة (بما فيها فحص الأدوار/الفرع) قبل إصدار أي توكن حتى
 93:         // لا يتخلف توكن يتيم عند الرفض.
 94:         $user->load(['branch', 'roles.permissions', 'permissions']);
 95:         $redirect = $this->destinations->resolve($user);
 96: 
 97:         // M9: حد لتوكنات الموظفين (مثل العملاء والموردين) داخل transaction،
 98:         // مع تنظيف المنتهية أولًا حتى لا يُحرم النشطون.
 99:         $token = DB::transaction(function () use ($user): string {
100:             $user = User::query()->lockForUpdate()->findOrFail($user->id);
101:             if (! $user->is_active) {
102:                 throw new BusinessException('غير مصرح لك بالدخول كموظف أو الحساب غير نشط.', [], 401);
103:             }
104:             $user->tokens()->where(fn ($q) => $q->where('expires_at', '<=', now())
105:                 ->orWhere('created_at', '<=', now()->subMinutes((int) config('sanctum.expiration', 1440))))->delete();
106:             $limit = max(1, (int) config('auth.staff_max_tokens', 20));
107:             $old = $user->tokens()->orderByDesc('id')->skip($limit - 1)->pluck('id');
108:             if ($old->isNotEmpty()) {
109:                 $user->tokens()->whereIn('id', $old)->delete();
110:             }
111: 
112:             return $user->createToken('staff-token')->plainTextToken;
113:         });
114: 
115:         logger()->info('staff.handoff', ['user_id' => $user->id, 'result' => 'success']);
116: 
117:         return response()->json([
118:             'data' => UserResource::make($user)->resolve($request),
119:             'token' => $token,
120:             'redirect' => $redirect,
121:         ]);
122:     }
123: 
124:     public function me(Request $request): JsonResponse
125:     {
126:         $actor = $request->user('sanctum');
127: 
128:         if ($actor instanceof User) {
129:             abort_unless($actor->is_active, 403);
130:             $actor->load(['branch', 'roles.permissions', 'permissions']);
131:             $redirect = $this->destinations->resolve($actor);
132: 
133:             return response()->json(['actor' => ['type' => 'staff', 'subtype' => $redirect['destination']],
134:                 'redirect' => $redirect,
135:                 'data' => UserResource::make($actor)->resolve($request)]);
136:         }
137: 
138:         if ($actor instanceof SupplierUser) {
139:             // H5: أعد فحص الشركة هنا أيضًا — إيقافها بعد إصدار التوكن يجب أن
140:             // يمنع الجلسة فورًا لا عند انتهاء التوكن.
141:             abort_unless($actor->is_active && $actor->supplier_id !== null
142:                 && $actor->supplier?->is_active === true, 403);
143:             $actor->load('supplier');
144:             $redirect = $this->destinations->resolve($actor);
145: 
146:             return response()->json(['actor' => ['type' => 'supplier', 'subtype' => $redirect['destination']],
147:                 'redirect' => $redirect,
148:                 'data' => SupplierUserResource::make($actor)->resolve($request)]);
149:         }
150: 
151:         if ($actor instanceof Customer) {
152:             abort_if($actor->status === CustomerStatus::Suspended, 403);
153:             $redirect = $this->destinations->resolve($actor);
154: 
155:             return response()->json([
156:                 // M1: subtype هو الـ destination دائمًا (كما في login)، ونوع
157:                 // العميل في حقل منفصل حتى لا يبني الفرونت الوجهة من me خطأً.
158:                 'actor' => ['type' => 'customer', 'subtype' => $redirect['destination'],
159:                     'customer_type' => $actor->type->value, 'status' => $actor->status->value],
160:                 'redirect' => $redirect,
161:                 'data' => CustomerResource::make($actor)->resolve($request)]);
162:         }
163: 
164:         abort(401);
165:     }
166: 
167:     public function logout(Request $request): Response
168:     {
169:         $request->user('sanctum')?->currentAccessToken()?->delete();
170: 
171:         return response()->noContent();
172:     }
173: 
174:     private function issueSupplierToken(SupplierUser $user): string
175:     {
176:         // L1: الحد غير ذري — دخولان متزامنان يتجاوزانه. القفل داخل transaction.
177:         return DB::transaction(function () use ($user): string {
178:             $user = SupplierUser::query()->lockForUpdate()->findOrFail($user->id);
179:             if (! $user->is_active || $user->supplier_id === null || $user->supplier?->is_active !== true) {
180:                 throw new BusinessException('بيانات الدخول غير صحيحة.', [], 401);
181:             }
182:             $user->tokens()->where(fn ($q) => $q->where('expires_at', '<=', now())
183:                 ->orWhere('created_at', '<=', now()->subMinutes((int) config('sanctum.expiration', 1440))))->delete();
184:             $limit = max(1, (int) config('auth.supplier_max_tokens', 5));
185:             $old = $user->tokens()->orderByDesc('id')->skip($limit - 1)->pluck('id');
186:             if ($old->isNotEmpty()) {
187:                 $user->tokens()->whereIn('id', $old)->delete();
188:             }
189: 
190:             return $user->createToken('supplier-token')->plainTextToken;
191:         });
192:     }
193: 
194:     /**
195:      * @param  array{app: string, path: string, destination: string}  $redirect
196:      * @param  array<string, mixed>  $data
197:      */
198:     private function respond(string $type, array $redirect, ?string $token, ?string $handoff, array $data, ?string $status, ?string $customerType = null, ?bool $cartMerged = null): JsonResponse
199:     {
200:         return response()->json(array_filter([
201:             'message' => 'تم تسجيل الدخول بنجاح',
202:             // M1: customer_type منفصل عن subtype (الوجهة) حتى لا يبني الفرونت
203:             // الوجهة من نوع العميل خطأً.
204:             'actor' => array_filter(['type' => $type, 'subtype' => $redirect['destination'], 'status' => $status,
205:                 'customer_type' => $customerType], fn ($v) => $v !== null),
206:             'redirect' => $redirect,
207:             'token' => $token,
208:             'handoff_code' => $handoff,
209:             'data' => $data,
210:             'cart_merged' => $cartMerged,
211:         ], fn ($v, $k) => $v !== null || $k === 'handoff_code' || $k === 'token', ARRAY_FILTER_USE_BOTH));
212:     }
213: } 1: <?php
