15: final class LoginDestinationResolver
16: {
17:     /** @return array{app: string, path: string, destination: string} */
18:     public function resolve(User|SupplierUser|Customer $actor, ?string $requested = null): array
19:     {
20:         if ($actor instanceof User) {
21:             $roles = $actor->getRoleNames();
22:             if ($roles->isEmpty()) {
23:                 throw new BusinessException('حسابك غير مرتبط بأي صلاحية. تواصل مع الإدارة.', [], 403);
24:             }
25:             if ($roles->count() === 1 && $roles->first() === StaffRole::Cashier->value) {
26:                 // M14: الفرع المحذوف أو الموقوف يُوجَّه للـ POS خطأً — ارفضه هنا
27:                 // بدل واجهة تعمل جزئيًا.
28:                 if ($actor->branch_id === null || $actor->branch === null || ! $actor->branch->is_active) {
29:                     throw new BusinessException('حسابك غير مرتبط بفرع نشط.', [], 403);
30:                 }
31: 
32:                 return ['app' => 'backoffice', 'path' => '/pos', 'destination' => 'pos'];
33:             }
34: 
35:             return ['app' => 'backoffice', 'path' => '/dashboard', 'destination' => 'admin'];
36:         }
37: 
38:         if ($actor instanceof SupplierUser) {
39:             return ['app' => 'web', 'path' => $this->safe($requested, '/supplier') ?? '/supplier', 'destination' => 'supplier'];
40:         }
41: 
42:         if ($actor->type === CustomerType::Retail) {
43:             // L3: المرفوض (بقرار إداري) كان يُوجَّه لـ '/' المعطلة بالكامل —
44:             // وجّهه لصفحة الحالة التي تعرض سبب الرفض (مسموحة للمرفوض).
45:             if ($actor->status === CustomerStatus::Rejected) {
46:                 return ['app' => 'web', 'path' => '/wholesale/application-status', 'destination' => 'wholesale_pending'];
47:             }
48:             $path = $this->safe($requested, '/');
49:             if ($path !== null && (str_starts_with($path, '/wholesale') || str_starts_with($path, '/supplier') || str_starts_with($path, '/auth'))) {
50:                 $path = null;
51:             }
52: 
53:             return ['app' => 'web', 'path' => $path ?? '/', 'destination' => 'retail'];
54:         }
55: 
56:         if ($actor->status === CustomerStatus::Approved) {
57:             return ['app' => 'web', 'path' => $this->safe($requested, '/wholesale') ?? '/wholesale', 'destination' => 'wholesale'];
58:         }
59: 
60:         return ['app' => 'web', 'path' => '/wholesale/application-status', 'destination' => 'wholesale_pending'];
61:     }
62: 
63:     private function safe(?string $path, string $prefix): ?string
64:     {
65:         if ($path === null || $path === '') {
66:             return null;
67:         }
68: 
69:         $decoded = rawurldecode($path);
70:         $pathname = explode('?', explode('#', $decoded, 2)[0], 2)[0];
71:         if (! str_starts_with($decoded, '/') || str_starts_with($decoded, '//')
72:             || str_contains($decoded, '\\') || str_contains($decoded, '://')
73:             || preg_match('/[\x00-\x20\x7f]/', $decoded)
74:             || array_intersect(explode('/', $pathname), ['.', '..']) !== []
75:             || ($prefix !== '/' && $pathname !== $prefix && ! str_starts_with($pathname, $prefix.'/'))) {
76:             return null;
77:         }
78: 
79:         if ($prefix === '/' && preg_match('~^/(auth|supplier|wholesale)(/|$)~', $pathname)) {
80:             return null;
81:         }
82: 
83:         return $path;
84:     }
