 7: use App\Models\User;
 8: use Illuminate\Contracts\Cache\LockTimeoutException;
 9: use Illuminate\Support\Facades\Cache;
10: use Illuminate\Support\Str;
11: 
12: final class StaffHandoffService
13: {
14:     private const TTL_SECONDS = 60;
15: 
16:     public function issue(User $user): string
17:     {
18:         $code = Str::random(64);
19:         Cache::put($this->key($code), ['user_id' => $user->id], now()->addSeconds(self::TTL_SECONDS));
20: 
21:         return $code;
22:     }
23: 
24:     /** @return array{user_id:int}|null */
25:     public function consume(string $code): ?array
26:     {
27:         // Cache::pull alone is a read followed by delete on database/Redis stores.
28:         // Serialize consumers so concurrent exchanges cannot issue two tokens.
29:         // M8: block() يرمي LockTimeoutException لو تعذّر القفل (تزامن/بطء) —
30:         // تُعامل ككود مستهلك (null) في الكنترولر بدل 500.
31:         try {
32:             return Cache::lock($this->key($code).':lock', 10)
33:                 ->block(5, fn (): ?array => Cache::pull($this->key($code)));
34:         } catch (LockTimeoutException $exception) {
35:             report($exception);
36: 
37:             return null;
38:         }
39:     }
40: 
41:     private function key(string $code): string
42:     {
43:         return 'auth:handoff:'.hash('sha256', $code);
44:     }
