18:     public function attempt(string $login, string $password): User|SupplierUser|Customer
19:     {
20:         $login = trim($login);
21: 
22:         if (str_contains($login, '@')) {
23:             $email = mb_strtolower($login);
24: 
25:             // H1: ثبّت التكلفة دائمًا — افحص الباسورد مقابل الجداول الثلاثة
26:             // حتى لو لم يوجد صف، عبر dummy hash، فيكلّف أي إيميل ثلاث عمليات
27:             // bcrypt بغض النظر عن وجود الحساب، فلا يُستدل على وجوده بالتوقيت.
28:             $staff = User::query()->whereRaw('LOWER(email) = ?', [$email])->first();
29:             $staffPasswordOk = Hash::check($password, $staff?->password ?? CustomerAuthService::dummyHash());
30: 
31:             $supplierUser = SupplierUser::query()->whereRaw('LOWER(email) = ?', [$email])->first();
32:             $supplierPasswordOk = Hash::check($password, $supplierUser?->password ?? CustomerAuthService::dummyHash());
33: 
34:             // الأولوية للأعلى مرتبة عند تطابق الباسورد في أكثر من جدول.
35:             if ($staff !== null && $staffPasswordOk) {
36:                 $this->rehashIfNeeded($staff, $password);
37:                 if (! $staff->is_active) {
38:                     logger()->info('staff.login', ['user_id' => $staff->id, 'result' => 'inactive']);
39:                     throw new BusinessException('بيانات الدخول غير صحيحة.', [], 401);
40:                 }
41: 
42:                 logger()->info('staff.login', ['user_id' => $staff->id, 'result' => 'success']);
43: 
44:                 return $staff;
