53:                     && $supplierUser->supplier?->is_active === true;
54:                 if (! $supplierActive) {
55:                     logger()->info('supplier.login', ['supplier_user_id' => $supplierUser->id, 'result' => 'inactive']);
56:                     throw new BusinessException('بيانات الدخول غير صحيحة.', [], 401);
57:                 }
58: 
59:                 logger()->info('supplier.login', ['supplier_user_id' => $supplierUser->id, 'result' => 'success']);
60: 
61:                 return $supplierUser;
62:             }
63: 
64:             if ($staff !== null || $supplierUser !== null) {
65:                 logger()->info('unified.login', ['result' => 'wrong_password']);
