 17: class CustomerPhoneVerificationService
 18: {
 19:     public function send(string $phone): void
 20:     {
 21:         if (Customer::withTrashed()->where('phone', $phone)->exists()) {
 22:             return;
 23:         }
 24:         $code = (string) random_int(100000, 999999);
 25:         $key = hash('sha256', $phone);
 26:         $created = DB::transaction(function () use ($key, $code): bool {
 27:             DB::table('customer_phone_verifications')->insertOrIgnore([
 28:                 'phone_key' => $key, 'code_hash' => '', 'created_at' => now()->subDay(), 'expires_at' => now()->subDay(),
 29:             ]);
 30:             $row = DB::table('customer_phone_verifications')->where('phone_key', $key)->lockForUpdate()->first();
 31:             if ($row->verified_at !== null && now()->lt($row->expires_at)) {
 32:                 return false;
 33:             }
 34:             if (now()->subSeconds(60)->lt($row->created_at) || ! app(CustomerMessageBudget::class)->claim('verify:'.$key)) {
 35:                 return false;
 36:             }
 37:             DB::table('customer_phone_verifications')->where('phone_key', $key)->update([
 38:                 'code_hash' => Hash::make($code), 'proof_hash' => null, 'attempts' => 0, 'verified_at' => null,
 39:                 'created_at' => now(), 'expires_at' => now()->addMinutes(10),
 40:             ]);
 41: 
 42:             return true;
 43:         });
 44:         if ($created) {
 45:             try {
 46:                 Notification::route('customer_sms', $phone)->notify(new CustomerPhoneVerificationCode($code));
 47:                 logger()->info('Customer OTP delivered.');
 48:             } catch (\Throwable $exception) {
 49:                 logger()->error('Customer OTP delivery failed.', ['exception' => $exception::class]);
 50:                 throw $exception;
 51:             }
 52:         }
 53:     }
 54: 
 55:     public function verify(string $phone, string $code): string
 56:     {
 57:         $proof = DB::transaction(function () use ($phone, $code): ?string {
 58:             $key = hash('sha256', $phone);
 59:             $row = DB::table('customer_phone_verifications')->where('phone_key', $key)->lockForUpdate()->first();
 60:             $valid = Hash::check($code, $row?->code_hash ?: CustomerAuthService::dummyHash());
 61:             if ($row === null || $row->attempts >= 5 || now()->gte($row->expires_at) || $row->verified_at !== null) {
 62:                 return null;
 63:             }
 64:             DB::table('customer_phone_verifications')->where('phone_key', $key)->increment('attempts');
 65:             if (! $valid) {
 66:                 return null;
 67:             }
 68:             $proof = Str::random(64);
 69:             DB::table('customer_phone_verifications')->where('phone_key', $key)->update([
 70:                 'proof_hash' => hash('sha256', $proof), 'verified_at' => now(), 'expires_at' => now()->addMinutes(10),
 71:             ]);
 72: 
 73:             return $proof;
 74:         });
 75:         if ($proof === null) {
 76:             throw new BusinessException('رمز التحقق غير صالح أو انتهت صلاحيته.');
 77:         }
 78: 
 79:         return $proof;
 80:     }
 81: 
 82:     public function requireProof(Request $request): void
 83:     {
 84:         if (! config('auth.require_phone_verification')) {
 85:             return;
 86:         }
 87:         $phone = $request->input('phone');
 88:         $proof = $request->input('phone_verification_token');
 89:         if (! is_string($phone) || ! is_string($proof) || strlen($proof) !== 64 || ! $this->validProof($phone, $proof)) {
 90:             throw ValidationException::withMessages(['phone_verification_token' => 'تحقق من ملكية رقم الهاتف أولًا.']);
 91:         }
 92:     }
 93: 
 94:     private function validProof(string $phone, string $proof, bool $consume = false): bool
 95:     {
 96:         $query = DB::table('customer_phone_verifications')->where('phone_key', hash('sha256', $phone));
 97:         $row = ($consume ? $query->lockForUpdate() : $query)->first();
 98:         $stored = $row?->proof_hash ?? '';
 99:         $matches = strlen($stored) === 64 ? hash_equals($stored, hash('sha256', $proof))
100:             : ($stored !== '' && Hash::check($proof, $stored));
101:         $valid = $matches && $row !== null && $row->verified_at !== null && now()->lt($row->expires_at);
102:         if ($valid && $consume) {
103:             $query->delete();
104:         }
105: 
106:         return $valid;
107:     }
108: 
109:     public function consume(array $data): bool
110:     {
111:         if (! config('auth.require_phone_verification')) {
112:             return false;
113:         }
114:         if (! $this->validProof($data['phone'], $data['phone_verification_token'] ?? '', true)) {
115:             throw new BusinessException('إثبات ملكية الهاتف غير صالح أو تم استخدامه.');
116:         }
117: 
118:         return true;
119:     }
