116:     private function login(array $body, ?string $cartSession = null)
117:     {
118:         // حراس Sanctum يخزّنون المستخدم المحلول داخل نفس التطبيق بين الطلبات،
119:         // لازم ننساهم قبل كل طلب وإلا تسرّب هوية طلب سابق (MultiTableAuthenticationTest يعمل نفس الشيء).
120:         Auth::forgetGuards();
121:         $headers = $cartSession !== null ? ['X-Cart-Session' => $cartSession] : [];
122: 
123:         return $this->postJson('/api/v1/auth/login', $body, $headers);
124:     }
125: 
126:     /** @return array{Authorization: string} */
127:     private function bearer(string $token): array
128:     {
129:         return ['Authorization' => 'Bearer '.$token];
130:     }
131: 
132:     private function authed(string $method, string $uri, string $token, array $data = [])
133:     {
134:         Auth::forgetGuards();
135: 
136:         return $method === 'get'
137:             ? $this->getJson($uri, $this->bearer($token))
138:             : $this->postJson($uri, $data, $this->bearer($token));
139:     }
