 23:     public function test_login_issues_staff_token_and_me_returns_branch_roles_and_permissions(): void
 24:     {
 25:         $branch = Branch::factory()->create();
 26:         $permission = Permission::create(['name' => 'users.view', 'guard_name' => 'staff']);
 27:         $role = Role::create(['name' => 'Manager', 'guard_name' => 'staff']);
 28:         $role->givePermissionTo($permission);
 29:         $staff = User::factory()->create([
 30:             'name' => 'Admin User',
 31:             'email' => 'admin@example.test',
 32:             'password' => 'secret-password',
 33:             'branch_id' => $branch->id,
 34:             'is_active' => true,
