 42:   const renderCanvasRef = useRef<() => void>(() => {});
 43:   const mousePosRef = useRef({ x: -1000, y: -1000, isHovering: false });
 44: 
 45:   const W = 560;
 46:   const H = 640;
 47: 
 48: 
 49:   // Translations
 50:   const t = {
 51:     en: {
 52:       signInTitle: 'Sign In',
 53:       signInSub: 'Sign in to your Alfarid account',
 54:       loginLabel: 'Email or mobile number',
 55:       loginPlaceholder: 'Enter your email or mobile number',
 56:       wholesaleRegister: 'Register as a wholesale trader',
 57:       handoffExpired: 'The login link has expired, please sign in again.',
 58:       passwordLabel: 'Password',
 59:       passwordPlaceholder: 'Enter your password',
 60:       forgotPassword: 'Forgot Password?',
 61:       signInBtn: 'Sign In',
 62:       createAccount: 'Create an Account',
 63: 
 64:     },
 65:     ar: {
 66:       signInTitle: 'تسجيل الدخول',
 67:       signInSub: 'سجّل الدخول إلى حسابك في الفريد',
 68:       loginLabel: 'البريد الإلكتروني أو رقم الموبايل',
 69:       loginPlaceholder: 'أدخل بريدك الإلكتروني أو رقم موبايلك',
