 81:   // Canvas drawing routine
 82:   const renderCanvas = useCallback(() => {
 83:     const canvas = canvasRef.current;
 84:     if (!canvas) return;
 85:     const ctx = canvas.getContext('2d');
 86:     if (!ctx) return;
 87: 
 88:     ctx.fillStyle = '#ffffff';
 89:     ctx.fillRect(0, 0, W, H);
 90: 
 91:     const activePixels = birkinPixelsRef.current;
 92:     if (!activePixels) return;
 93: 
 94:     const step = gridStep;
 95:     const half = step / 2;
 96:     const { x: mx, y: my, isHovering: isHover } = mousePosRef.current;
 97: 
 98:     ctx.fillStyle = '#09090b';
 99: 
100:     for (let y = Math.floor(half); y < H; y += step) {
101:       for (let x = Math.floor(half); x < W; x += step) {
102:         const idx = (y * W + x) * 4;
103:         const luma = activePixels[idx] / 255.0;
104:         const dark = 1.0 - luma;
105:         if (dark < 0.06) continue;
106: 
107:         let drawX = x;
108:         let drawY = y;
109:         let scaleBoost = 1.0;
110: 
111:         if (isHover) {
112:           const dx = x - mx;
113:           const dy = y - my;
114:           const dist = Math.sqrt(dx * dx + dy * dy);
115:           if (dist < 110) {
116:             const factor = 1.0 - dist / 110.0;
117:             drawX += (dx / (dist + 1)) * factor * 2.2;
118:             drawY += (dy / (dist + 1)) * factor * 2.2;
119:             scaleBoost = 1.0 + factor * 0.16;
120:           }
121:         }
122: 
123:         const r = Math.pow(dark, 0.92) * (step * 0.68) * scaleBoost;
124:         if (r < 0.45) continue;
125: 
126:         // Diamond dot
127:         ctx.beginPath();
128:         ctx.moveTo(drawX, drawY - r);
129:         ctx.lineTo(drawX + r, drawY);
130:         ctx.lineTo(drawX, drawY + r);
131:         ctx.lineTo(drawX - r, drawY);
132:         ctx.closePath();
133:         ctx.fill();
134: 
135:         // White micro center dot
136:         if (dark > 0.76 && r > 2.4) {
137:           const ir = (dark - 0.74) * (step * 0.3);
138:           if (ir >= 0.7) {
139:             ctx.save();
140:             ctx.fillStyle = '#ffffff';
141:             ctx.beginPath();
142:             ctx.arc(drawX, drawY, ir, 0, Math.PI * 2);
143:             ctx.fill();
144:             ctx.restore();
145:           }
146:         }
147:       }
148:     }
149: 
150:   }, []);
151: 
152:   useEffect(() => {
153:     renderCanvasRef.current = renderCanvas;
154:     renderCanvas();
155:   }, [renderCanvas]);
156: 
157:   // Extract pixel buffers on mount
158:   useEffect(() => {
159:     const offCanvas = document.createElement('canvas');
160:     offCanvas.width = W;
161:     offCanvas.height = H;
162:     const offCtx = offCanvas.getContext('2d', { willReadFrequently: true });
163:     if (!offCtx) return;
164: 
165:     const extract = (img: HTMLImageElement) => {
166:       offCtx.fillStyle = '#ffffff';
167:       offCtx.fillRect(0, 0, W, H);
168:       offCtx.drawImage(img, 0, 0, W, H);
169:       return offCtx.getImageData(0, 0, W, H).data;
170:     };
171: 
172:     const bImg = new Image();
173:     bImg.src = BIRKIN_IMG_DATA;
174:     bImg.onload = () => {
175:       birkinPixelsRef.current = extract(bImg);
