187:     mousePosRef.current = {
188:       x: ((clientX - rect.left) / rect.width) * W,
189:       y: ((clientY - rect.top) / rect.height) * H,
190:       isHovering: true,
191:     };
192:     requestAnimationFrame(renderCanvas);
193:   };
194: 
195:   const handlePointerLeave = () => {
196:     mousePosRef.current.isHovering = false;
