  6: export async function loginUnified(login: string, password: string, redirect?: string | null) {
  7:   const res = await authEndpoints.login({ login, password, redirect: redirect ?? undefined },
  8:     typeof window !== 'undefined' ? localStorage.getItem(CART_KEY) : null);
  9: 
 10:   if (res.redirect.app === 'backoffice') {
 11:     // M9: جلسة عميل/مورد قائمة توكنها يبقى صالحًا 24 ساعة بعد clear المحلي —
 12:     // أبطلها في الخادم أولًا (best-effort) قبل مسح الجلسة المحلية.
 13:     try { if (useAuthStore.getState().token) await authEndpoints.logout(); } catch { /* best-effort */ }
 14:     useAuthStore.getState().clear();
 15:     // M7: الكود في الـ fragment لا في الـ query — الـ fragment لا يُرسل
 16:     // للخادم ولا يظهر في الـ Referer أو سجلات nginx.
 17:     const url = `${process.env.NEXT_PUBLIC_BACKOFFICE_URL ?? 'http://localhost:5173'}/auth/callback#code=${encodeURIComponent(res.handoff_code!)}`;
 18:     window.location.assign(url);
 19:     return null;
 20:   }
 21: 
 22:   useAuthStore.getState().setSession({
 23:     token: res.token!, actorType: res.actor.type as 'customer' | 'supplier',
 24:     destination: res.actor.subtype, home: res.redirect.path, user: res.data,
 25:   });
 26:   // M10: الدمج قد يفشل في الخادم (cart_merged=false) — أبقِ cart_session
 27:   // ليُعاد دمجه لاحقًا بدل حذفه مع توكن يتيم جديد.
 28:   if (res.actor.type === 'customer' && res.cart_merged !== false) localStorage.removeItem(CART_KEY);
 29:   return res.redirect.path;
 30: }
