 52: export async function registerWeb(input: RegistrationInput, wholesale: boolean, documents: File[] = []) {
 53:   let body: RegistrationInput | FormData = input;
 54:   if (wholesale) {
 55:     body = new FormData();
 56:     Object.entries(input).forEach(([key, value]) => {
 57:       if (value !== undefined && value !== '') (body as FormData).append(key, value);
 58:     });
 59:     documents.forEach((file) => (body as FormData).append('documents[]', file));
 60:   }
 61:   const session = localStorage.getItem(CART_KEY);
 62:   const response = await defaultApiClient.post<RegistrationResponse>(
 63:     wholesale ? '/api/v1/wholesale/auth/register' : '/api/v1/store/auth/register', body,
 64:     { headers: {
 65:       ...(wholesale ? { 'Content-Type': 'multipart/form-data' } : {}),
 66:       ...(!wholesale && session ? { 'X-Cart-Session': session } : {}),
 67:     } },
 68:   );
 69:   const home = wholesale ? '/wholesale/application-status' : '/';
 70:   useAuthStore.getState().setSession({
 71:     token: response.data.token, actorType: 'customer',
 72:     destination: wholesale ? 'wholesale_pending' : 'retail', home, user: response.data.data,
 73:   });
 74:   if (!wholesale) localStorage.removeItem(CART_KEY);
 75:   return home;
 76: }
