27: export function createApiClient(config: ApiClientConfig = {}): AxiosInstance {
28:   const envBaseUrl = typeof process !== 'undefined' && process.env 
29:     ? (process.env.NEXT_PUBLIC_API_URL || process.env.VITE_API_URL) 
30:     : undefined;
31: 
32:   const instance = axios.create({
33:     baseURL: config.baseURL || envBaseUrl || 'http://localhost:8000',
34:     timeout: 30000,
35:     withCredentials: config.withCredentials ?? false,
36:     headers: {
37:       'Content-Type': 'application/json',
38:       Accept: 'application/json',
39:       'X-Requested-With': 'XMLHttpRequest',
40:     },
41:   });
42: 
43:   instance.interceptors.request.use((reqConfig: InternalAxiosRequestConfig) => {
44:     const token = config.getToken ? config.getToken() : activeToken;
45:     if (token && reqConfig.headers) {
46:       reqConfig.headers.Authorization = `Bearer ${token}`;
47:     }
48:     return reqConfig;
49:   });
50: 
51:   instance.interceptors.response.use(
52:     (response) => response,
53:     (error) => {
54:       const isSignInRequest = ['/api/v1/auth/login', '/api/v1/auth/handoff/exchange']
55:         .some((path) => error.config?.url?.split('?')[0] === path);
56:       if (error.response?.status === 401 && !isSignInRequest) {
57:         if (config.onUnauthorized) {
58:           config.onUnauthorized();
59:         } else if (unauthorizedHandler) {
60:           unauthorizedHandler();
61:         }
62:       }
63:       return Promise.reject(error);
64:     }
65:   );
66: 
67:   return instance;
68: }
