119:     public function sendPasswordReset(?string $email, ?string $phone): void
120:     {
121:         if (! $email && ! $phone) {
122:             return;
123:         }
124: 
125:         $customer = Customer::query()
126:             ->when($email, fn ($q) => $q->whereNotNull('email_verified_at')->whereRaw('LOWER(email) = ?', [mb_strtolower(trim($email))]),
127:                 fn ($q) => $q->where('phone', Customer::normalizePhone($phone)))
128:             ->first();
129: 
130:         if ($customer === null || $customer->status === CustomerStatus::Suspended) {
131:             return;
132:         }
133: 
134:         $plainToken = Str::random(64);
135:         $key = $customer->getEmailForPasswordReset();
136: 
137:         $stored = DB::transaction(function () use ($customer, $key, $plainToken, $email): bool {
138:             $current = Customer::query()->lockForUpdate()->find($customer->id);
139:             if ($current === null || $current->status === CustomerStatus::Suspended) {
140:                 return false;
141:             }
142:             if ($email && ($current->email_verified_at === null || $current->email !== mb_strtolower(trim($email)))) {
143:                 return false;
144:             }
145:             $existing = DB::table('password_reset_tokens')->where('email', $key)->first();
146:             if ($existing && now()->subSeconds(60)->lt($existing->created_at)) {
147:                 return false;
148:             }
149:             if (! app(CustomerMessageBudget::class)->claim('reset:customer:'.$customer->id, sms: ! $email)) {
150:                 return false;
151:             }
152:             DB::table('password_reset_tokens')->updateOrInsert(
153:                 ['email' => $key], ['token' => hash('sha256', $plainToken), 'created_at' => now()],
154:             );
155: 
156:             return true;
157:         });
158:         if (! $stored) {
159:             return;
160:         }
161: 
162:         try {
163:             $customer->notify(new CustomerPasswordReset($plainToken, $email ? 'mail' : CustomerSmsChannel::class));
164:         } catch (\Throwable $exception) {
165:             report($exception);
166:         }
167:     }
