169:     public function resetPassword(array $data): void
170:     {
171:         $dummyHash = self::dummyHash();
172:         DB::transaction(function () use ($data, $dummyHash): void {
173:             $customer = Customer::query()
174:                 ->when(! empty($data['email']), fn ($q) => $q->whereNotNull('email_verified_at')->whereRaw('LOWER(email) = ?', [mb_strtolower(trim($data['email']))]),
175:                     fn ($q) => $q->where('phone', $data['phone']))
176:                 ->lockForUpdate()->first();
177:             $key = $customer?->getEmailForPasswordReset();
178:             $row = DB::table('password_reset_tokens')->where('email', $key)->lockForUpdate()->first();
179:             $storedToken = $row?->token ?? '';
180:             $validToken = strlen($storedToken) === 64 ? hash_equals($storedToken, hash('sha256', $data['token']))
181:                 : Hash::check($data['token'], $storedToken ?: $dummyHash);
182:             if ($customer === null || $customer->status === CustomerStatus::Suspended || $row === null
183:                 || $row->created_at === null || now()->subMinutes(60)->gte($row->created_at)
184:                 || now()->lt($row->created_at) || ! $validToken) {
185:                 throw new BusinessException('رمز الاستعادة غير صالح أو انتهت صلاحيته.');
186:             }
187:             $customer->forceFill(['password' => $data['password'], 'remember_token' => Str::random(60)])->save();
188:             $customer->tokens()->delete();
189:             DB::table('password_reset_tokens')->where('email', $key)->delete();
190:             CustomerAuditLog::record($customer, 'password_reset', null);
191:         });
192:     }
