194:     /** إصدار توكن Sanctum باسم القناة (store-token / wholesale-token). */
195:     public function issueToken(Customer $customer, string $name): string
196:     {
197:         return DB::transaction(function () use ($customer, $name): string {
198:             $customer = Customer::query()->lockForUpdate()->findOrFail($customer->id);
199:             if ($customer->status === CustomerStatus::Suspended) {
200:                 throw new BusinessException('هذا الحساب موقوف.', [], 403);
201:             }
202: 
203:             $expiry = config('sanctum.expiration');
204:             $customer->tokens()->where(fn ($q) => $q->where('expires_at', '<=', now())
205:                 ->when($expiry, fn ($q) => $q->orWhere('created_at', '<=', now()->subMinutes((int) $expiry))))->delete();
206:             $limit = max(1, (int) config('auth.customer_max_tokens', 10));
207:             $old = $customer->tokens()->orderByDesc('id')->skip($limit - 1)->pluck('id');
208:             if ($old->isNotEmpty()) {
209:                 $customer->tokens()->whereIn('id', $old)->delete();
210:             }
211: 
212:             $token = $customer->createToken($name);
213:             CustomerAuditLog::record($customer, 'token_issued', null, ['token_id' => $token->accessToken->id, 'channel' => $name]);
214: 
215:             return $token->plainTextToken;
216:         });
217:     }
