 18: /**
 19:  * سلة التسوق للزائر والعميل المسجل.
 20:  * - الزائر: سلة مربوطة بـ cart_token (يُرسل في هيدر X-Cart-Session).
 21:  * - العميل: سلة مربوطة بحسابه؛ وعند تسجيل الدخول تُدمج سلة الزائر فيها.
 22:  * الأسعار دائمًا لحظية من PricingService (لا تُخزّن في السلة أبدًا).
 23:  */
 24: class CartService
 25: {
 26:     public function __construct(
 27:         protected PricingService $pricing,
 28:         protected StoreCatalogService $catalog,
 29:         protected CouponService $coupons,
 30:     ) {}
 31: 
 32:     /**
 33:      * سلة الزائر/العميل الحالية.
 34:      * - التوكن غير الـ UUID يُتجاهل تمامًا (M2)؛ وتوكن أي سلة جديدة
 35:      *   يُولّد على الخادم دائمًا (Cart::booted) ولا يُقبل مقترح العميل.
 36:      * - بوضع القراءة ($create=false) لا يُحفظ أي صف: تُرجع سلة فارغة
 37:      *   افتراضية حتى لا تملأ الزواحف جدول carts (M3).
 38:      * لو وُجدت سلة زائر بالتوكن وعميل مسجل، تُدمج فيها أولًا.
 39:      */
 40:     public function resolveCart(?Customer $customer, ?string $guestToken, bool $create = true): Cart
 41:     {
 42:         $guestToken = $guestToken !== null && Str::isUuid($guestToken) ? $guestToken : null;
 43: 
 44:         if ($customer !== null) {
 45:             $cart = $create
 46:                 ? $this->accountCart($customer)
 47:                 : (Cart::query()->where('customer_id', $customer->id)->first() ?? new Cart(['customer_id' => $customer->id]));
 48:             if ($create && $guestToken !== null && $guestToken !== $cart->cart_token) {
 49:                 $this->mergeGuestCart($customer, $guestToken);
 50:                 $cart = $cart->fresh();
 51:             }
 52: 
 53:             return $cart->loadMissing('items');
 54:         }
 55: 
 56:         $cart = $guestToken !== null
 57:             ? Cart::query()->where('cart_token', $guestToken)->whereNull('customer_id')->first()
 58:             : null;
 59:         if ($cart !== null) {
 60:             return $cart->loadMissing('items');
 61:         }
 62: 
 63:         return ($create ? Cart::create([]) : new Cart)->loadMissing('items');
 64:     }
 65: 
 66:     /**
 67:      * سلة حساب العميل الوحيدة — القيد الفريد على customer_id يحسم السباق (M6).
 68:      * createOrFirst يغلّف الإدراج في savepoint داخل المعاملات (F-10):
 69:      * firstOrCreate العادي إذا فشل إدراجه هنا — والدمج كله داخل transaction
 70:      * خارجية — ترك المعاملة aborted (25P02) فخرج 500 رغم الـ catch.
 71:      */
 72:     private function accountCart(Customer $customer): Cart
 73:     {
 74:         return Cart::query()->where('customer_id', $customer->id)->first()
 75:             ?? Cart::query()->createOrFirst(['customer_id' => $customer->id]);
 76:     }
 77: 
 78:     /** دمج سلة زائر (بالتوكن) في سلة حساب العميل — تُستدعى عند تسجيل الدخول. */
 79:     public function mergeGuestCart(Customer $customer, ?string $guestToken): void
 80:     {
 81:         $guestToken = $guestToken !== null && Str::isUuid($guestToken) ? $guestToken : null;
 82:         if ($guestToken === null) {
 83:             return;
 84:         }
 85: 
 86:         // كل الدمج داخل transaction واحدة وسلة الزائر مقفولة: طلبات متوازية
 87:         // بعد تسجيل الدخول بنفس التوكن لا تضاعف الكميات (M6)
 88:         DB::transaction(function () use ($customer, $guestToken): void {
 89:             $guest = Cart::query()->where('cart_token', $guestToken)->whereNull('customer_id')
 90:                 ->lockForUpdate()->first();
 91:             if ($guest === null) {
 92:                 return;
 93:             }
 94:             if (! $guest->items()->exists()) {
 95:                 $guest->delete();
 96: 
 97:                 return;
 98:             }
 99: 
100:             $account = $this->accountCart($customer);
101:             // الدمج يحترم سقوف السلة (M2): بغير ذلك بضع سلال زائر بحد البنود
102:             // تُنتج سلة حساب بمئات البنود فتُلغي حماية F15
103:             $maxLines = (int) config('store.max_cart_lines', 50);
104:             $lineCap = $this->lineQtyCap($customer);
105:             $accountQty = $account->items()->pluck('qty', 'product_variant_id')
106:                 ->map(fn ($qty): float => (float) $qty)->all();
107:             $accountLines = count($accountQty);
108: 
109:             foreach ($guest->items as $item) {
110:                 $variantId = (int) $item->product_variant_id;
111:                 $existingQty = $accountQty[$variantId] ?? null;
112:                 $isNew = $existingQty === null;
113: 
114:                 // بنود جديدة فوق السقف تُتجاهل (لا تُفشل تسجيل الدخول)
115:                 if ($isNew && $maxLines > 0 && $accountLines >= $maxLines) {
116:                     continue;
117:                 }
118: 
119:                 $qty = (float) $item->qty;
120:                 if ($lineCap > 0) {
121:                     $allowed = $lineCap - (float) ($existingQty ?? 0);
122:                     if ($allowed <= 0) {
123:                         continue;
124:                     }
125:                     $qty = min($qty, $allowed);
126:                 }
127: 
128:                 // UPSERT ذرّي: دمج متزامن لا يصطدم بقيد التفرد (F-09)
129:                 CartItem::query()->upsert(
130:                     [[
131:                         'cart_id' => $account->id,
132:                         'product_variant_id' => $variantId,
133:                         'qty' => $qty,
134:                         'created_at' => now(),
135:                         'updated_at' => now(),
136:                     ]],
137:                     ['cart_id', 'product_variant_id'],
138:                     ['qty' => DB::raw('cart_items.qty + EXCLUDED.qty'), 'updated_at' => now()],
139:                 );
140: 
141:                 $accountQty[$variantId] = (float) ($existingQty ?? 0) + $qty;
142:                 if ($isNew) {
143:                     $accountLines++;
144:                 }
145:             }
146:             if ($account->coupon_id === null && $guest->coupon_id !== null) {
147:                 $account->update(['coupon_id' => $guest->coupon_id]);
148:             }
149:             $guest->items()->delete();
150:             $guest->delete();
151:         });
152:     }
