197:     public function updateItemQty(Cart $cart, ?Customer $customer, int $variantId, float $qty): Cart
198:     {
199:         if ($qty <= 0) {
200:             return $this->removeItem($cart, $variantId);
201:         }
202: 
203:         return DB::transaction(function () use ($cart, $customer, $variantId, $qty): Cart {
204:             // قفل صف السلة (F19) بنفس منطق addItem
205:             $cart = Cart::query()->lockForUpdate()->findOrFail($cart->id);
206:             $variant = $this->purchasableVariant($variantId);
207:             $this->assertLineQty($customer, $qty);
208:             $this->assertAvailable($variantId, $qty);
209:             $this->assertPriced($variant, $customer, $qty);
210: 
211:             // UPSERT ذرّي بنفس منطق addItem — updateOrCreate كان يصطدم
212:             // بقيد التفرد تحت التزامن (F-09)، وهنا القيمة مطلقة لا تراكمية
213:             CartItem::query()->upsert(
214:                 [[
215:                     'cart_id' => $cart->id,
216:                     'product_variant_id' => $variantId,
217:                     'qty' => $qty,
218:                     'created_at' => now(),
219:                     'updated_at' => now(),
220:                 ]],
221:                 ['cart_id', 'product_variant_id'],
222:                 ['qty' => $qty, 'updated_at' => now()],
223:             );
224: 
225:             return $cart->fresh('items');
226:         });
227:     }
