279:     /**
280:      * ملخص السلة المالي بالأسعار اللحظية.
281:      *
282:      * @return array{subtotal: float, pricing_discount: float, items_total: float, coupon_discount: float, total: float, coupon_code: string|null}
283:      */
284:     /**
285:      * @param  array<int, array<string, mixed>>|null  $lines  بنود محسوبة مسبقًا
286:      *                                                        لتجنب إعادة التسعير (M15)
287:      */
288:     public function totals(Cart $cart, ?Customer $customer, ?array $lines = null): array
289:     {
290:         $lines ??= $this->pricedLines($cart, $customer);
291:         $subtotal = 0.0;
292:         $itemsTotal = 0.0;
293:         foreach ($lines as $line) {
294:             if ($line['unit_price'] === null) {
295:                 continue;
296:             }
297:             // كل سطر يُقرَّب أولًا ثم تُجمع القيم المقرّبة (M17)
298:             $subtotal += round((float) $line['base_price'] * $line['qty'], 2);
299:             $itemsTotal += $line['line_total'];
300:         }
301: 
302:         // الخصم السعري = الفرق بين الإجماليين المقرّبين، لا مجموع فروق
303:         // السطور المقرّبة (F-26) حتى لا يظهر فرق قرش بين العرض والمحصّل.
304:         // ‏(L6) سعر مخصص أعلى من الأساسي لا يصنع خصمًا سالبًا: يُرفع المرجع
305:         // لسعر البيع الفعلي، فلا يزيد الخصم السالب الإجمالي المحصّل.
306:         if ($subtotal < $itemsTotal) {
307:             $subtotal = $itemsTotal;
308:             $pricingDiscount = 0.0;
309:         } else {
310:             $pricingDiscount = round($subtotal - $itemsTotal, 2);
311:         }
312: 
313:         $couponDiscount = 0.0;
