140:                 Limit::perMinute(5)->by('checkout-phone:'.$phoneKey),
141:                 Limit::perDay(20)->by('checkout-phone-day:'.$phoneKey),
142:             ];
143:         });
144:         RateLimiter::for('order-tracking', fn (Request $request) => [
145:             Limit::perMinute(10)->by('order-tracking-ip:'.$request->ip()),
146:         ]);
147:         RateLimiter::for('webhooks', fn (Request $request) => [
148:             Limit::perMinute(120)->by('webhooks-ip:'.$request->ip()),
149:         ]);
150: 
151:         RateLimiter::for('supplier-login', function (Request $request): array {
152:             $email = $request->input('email');
153:             $normalizedEmail = is_string($email)
154:                 ? Str::transliterate(Str::lower(trim($email)))
155:                 : '';
156:             $emailKey = hash('sha256', $normalizedEmail);
157: 
158:             return [
159:                 Limit::perMinute(5)->by('supplier-login-email:'.$emailKey),
160:                 Limit::perHour(30)->by('supplier-login-email-hour:'.$emailKey),
161:                 Limit::perMinute(120)->by('supplier-login-ip:'.($request->ip() ?? 'unknown')),
162:             ];
163:         });
164: 
165:         RateLimiter::for('admin-login', function (Request $request): array {
166:             $email = $request->input('email');
167:             $normalizedEmail = is_string($email)
168:                 ? Str::transliterate(Str::lower(trim($email)))
169:                 : '';
170:             $emailKey = hash('sha256', $normalizedEmail);
171: 
172:             return [
173:                 Limit::perMinute(5)->by('admin-login-email:'.$emailKey),
174:                 Limit::perHour(30)->by('admin-login-email-hour:'.$emailKey),
175:                 Limit::perMinute(120)->by('admin-login-ip:'.($request->ip() ?? 'unknown')),
176:             ];
177:         });
178: 
179:         RateLimiter::for('customer-password-reset', fn (Request $request) => [
180:             Limit::perMinute(config('auth.customer_limits.reset_ip_minute', 20))->by('customer-password-reset:'.$request->ip()),
181:             Limit::perDay(config('auth.customer_limits.reset_ip_day', 500))->by('customer-password-reset-day:'.$request->ip()),
182:             Limit::perMinute(5)->by('customer-password-reset-id:'.$identifierKey($request)),
183:             Limit::perDay(10)->by('customer-password-reset-id-day:'.$identifierKey($request)),
184:         ]);
185: 
186:         // حد تسجيل دخول الكاشير على نقطة البيع
187:         RateLimiter::for('pos-login', function (Request $request): array {
188:             $email = $request->input('email');
189:             $emailKey = hash('sha256', Str::lower(trim(is_string($email) ? $email : '')));
190: 
191:             return [
192:                 Limit::perMinute(5)->by('pos-login-email:'.$emailKey),
193:                 Limit::perHour(30)->by('pos-login-email-hour:'.$emailKey),
194:                 Limit::perMinute(120)->by('pos-login-ip:'.($request->ip() ?? 'unknown')),
195:             ];
196:         });
197: 
198:         // حد الدخول الموحد: بالـ IP وبالمعرّف (بريد/هاتف) معًا
199:         RateLimiter::for('unified-login', function (Request $request) {
200:             // H2: طبّع المعرّف بنفس منطق CustomerAuthService::login، وإلا كانت
201:             // كل صيغة هاتف (‎+20/0020/مسافات/أرقام عربية) بعدّاد مستقل.
202:             // M3: المدخل قد يكون array فيصل قبل الـ validation — لا تصبه لـ string.
203:             $raw = $request->input('login');
204:             $normalized = ! is_string($raw) || trim($raw) === ''
205:                 ? 'invalid'
206:                 : (str_contains($raw, '@')
207:                     ? Str::lower(trim($raw))
208:                     : Customer::normalizePhone($raw));
209:             $id = hash('sha256', $normalized);
210: 
211:             return [
212:                 // M6: حد الـ IP قابل للضبط (شبكات CGNAT والفروع المشتركة)، وحد
213:                 // المعرّف العام مخفف لمنع قفل حسابات الآخرين (lockout DoS) مع
214:                 // إبقاء حد ضيق لكل (IP + معرّف) ضد التخمين المركّز.
215:                 Limit::perMinute((int) config('auth.unified_login_ip_minute', 120))->by('ip:'.$request->ip()),
216:                 Limit::perMinute(5)->by('id:'.$id.':'.$request->ip()),
217:                 Limit::perHour((int) config('auth.unified_login_id_hour', 100))->by('id-hour:'.$id),
218:             ];
219:         });
220: 
221:         RateLimiter::for('unified-handoff', fn (Request $request) => Limit::perMinute(20)->by($request->ip()));
222: 
223:         // M8: الـ handoff يعتمد على cache مشترك يدعم الأقفال عبر الخوادم.
224:         // file/array يكسرانه بصمت على عدة nodes — نبّه في الإنتاج مبكرًا.
225:         if ($this->app->environment('production')
226:             && ! in_array((string) config('cache.default'), ['redis', 'database', 'memcached', 'dynamodb'], true)) {
227:             logger()->error('Staff handoff requires a shared lockable cache store in production.', [
228:                 'cache_default' => (string) config('cache.default'),
229:             ]);
230:         }
231:     }
232: }  1: # API Notes
  2: 
  3: ## Unified Login (`/api/v1/auth`) — the only login used by frontends
  4: 
  5: - `POST /api/v1/auth/login` — single entry point for staff, suppliers and
  6:   customers (email or phone + password, optional `redirect`). Account priority
  7:   for emails: `users` ← `supplier_users` ← `customers`. Staff get a one-time
  8:   `handoff_code` (never a token on the web domain); suppliers/customers get a
  9:   Bearer token directly.
 10: - `POST /api/v1/auth/handoff/exchange` — backoffice exchanges the one-time
 11:   `code` for a staff token. `GET /api/v1/auth/me` returns the actor +
 12:   redirect; `POST /api/v1/auth/logout` deletes the current token.
 13: - Deprecated (kept for backward compatibility + existing tests, do not use
 14:   from frontends): `admin/auth/login`, `store/auth/login`,
 15:   `supplier/auth/login`, `pos/auth/login`. `admin/me` and `admin/auth/logout`
 16:   remain in use by the backoffice.
 17: 
 18: ### Local unified-login verification
 19: 
 20: - Staff handoff codes expire after 60 seconds and are consumed under a cache
 21:   lock, so simultaneous exchanges cannot reuse a code. Exchange rechecks the
 22:   employee's current roles and branch before issuing a token.
 23: - Local defaults: storefront `3000`, backoffice `5173`, API `8000`. Copy each
 24:   application's `.env.example` when setting up a fresh checkout. For alternate
 25:   storefront ports, set `FRONTEND_URL` on the API and `VITE_WEB_URL` on the
 26:   backoffice to the same storefront origin.
 27: - To create local test accounts, set `UNIFIED_DEMO_PASSWORD` (at least 12
 28:   characters), then run `php artisan db:seed --class=UnifiedLoginDemoSeeder`
 29:   from `backend`. The seeder is restricted to local/testing environments and
 30:   does not reset existing accounts. Accounts use
 31:   `unified-{admin,cashier,supplier,retail,approved,pending,rejected,suspended}@example.test`.
 32:   Retail phone: `01070000001` / `+201070000001`.
 33: - `frontend/tests/unified-login.e2e.cjs` exercises actual browser flows using
 34:   Playwright and an installed Edge browser. Set `UNIFIED_DEMO_PASSWORD` and
 35:   optionally `E2E_WEB_URL`, `E2E_BACKOFFICE_URL`, `E2E_API_URL`, or
 36:   `E2E_BROWSER_CHANNEL`, then run `node tests/unified-login.e2e.cjs` from
 37:   `frontend` with Playwright available to Node. Results and desktop/mobile
 38:   captures are written to the ignored `test-results/unified-login/` folder.
 39: - Verification on 2026-10-21: the full backend suite passed 676 tests / 3452
 40:   assertions; a final authentication regression run passed 44 tests / 136
 41:   assertions, including the added cross-account registration check. Storefront
 42:   and backoffice production builds passed. The local database audit found no
 43:   emails shared between account tables. All 17 browser scenarios passed,
 44:   including mobile/desktop, role routing, callback replay, logout revocation,
 45:   wrong-password/suspension/rate-limit errors and staff-token origin isolation.
 46:   Browser verification used storefront port `3100` because another project
 47:   already occupied `3000`; the application's default configuration remains `3000`.
 48: - Sign-in, retail registration, password recovery/reset and wholesale
 49:   registration now switch forms inside the same white Birkin auth screen.
 50:   `/auth/register`, `/auth/forgot-password`, `/auth/reset-password` and
 51:   `/wholesale/register` also open the corresponding form directly without the
 52:   storefront header. Customer registration uses the existing store/wholesale
 53:   register endpoints, supports phone-verification proof and multipart business
 54:   documents, and stores the resulting customer session. OTP and recovery
 55:   delivery use the existing queue/mail/SMS configuration and require its worker.
 56: - `frontend/tests/auth-forms.e2e.cjs` covers inline navigation, direct URLs,
 57:   registration sessions, phone verification, recovery/reset, multipart uploads
 58:   and validation/rate-limit errors against mocked API responses. It uses the
 59:   same Playwright/browser setup and origin environment variables as the login
 60:   suite, without creating accounts or sending messages.
 61: - `/checkout` is an allowed retail redirect; its checkout UI is outside this
 62:   authentication task and is not implemented in this storefront yet.
 63: 
 64: ## Admin Categories (`/api/v1/admin/categories`)
 65: 
 66: - `GET /categories` — list with pagination (`per_page`, default 15, max 100), filters: `search`, `parent_id` (`root` for top-level), `is_active`. Use `?tree=1` for the full nested tree without pagination.
 67: - `GET /categories/{id}` — single category with parent, children and products count.
 68: - `POST /categories` — create (201). `slug` is generated automatically from `name_en` when omitted.
 69: - `PUT /categories/reorder` — body: `items: [{id, parent_id, sort_order}]`. Every item must explicitly include `parent_id`; use `null` for a root. The final tree is validated atomically, regardless of item order.
 70: - `DELETE /categories/{id}` — fails with 422 when the category has children or linked products, including soft-deleted references.
 71: - Maximum category depth is 3 levels; violations return 422.
 72: 
 73: ## Admin Brands (`/api/v1/admin/brands`)
 74: 
 75: - Same pattern as categories, without parent/tree/reorder. Logo is uploaded in the `logo` field
 76:   (jpg, jpeg, png, webp; SVG is rejected) and returned as `logo_url`.
 77: - Deleting a brand linked to products (including soft-deleted products) fails with 422.
 78: 
 79: ## Admin Products (`/api/v1/admin/products`)
 80: 
 81: - `GET /products` — filters: `search` (names, `code`, variant `sku`/`barcode`), `category_id`
 82:   (add `include_children=1` to include subcategories), `brand_id`, `status`, `sales_channel`,
 83:   `is_featured`; `sort`: `latest` (default), `oldest`, `name`. Response includes
 84:   `variants_count`, `min_retail_price`, `max_retail_price`.
 85: - `POST /products` — creates a `draft` and auto-assigns `code` (`P00001`…). If supplied, `status` must be `draft`; upload media after creation and then publish via update.
 86:   Optional `variants: [...]` can be sent with creation; a variant without `barcode` gets an
 87:   internal EAN-13 barcode (prefix `2`), and without `sku` gets `{product_code}-{n}`.
 88: - Publishing (`status: published`) requires the `products.publish` permission and a publishable
 89:   product: at least one active variant, retail/wholesale prices on all active variants according
 90:   to `sales_channel`, at least one image, and an active category with active ancestors. Violations return 422 with
 91:   `errors.status` listing every problem; missing publish permission returns 403.
 92: - Moving into or out of `published` requires `products.publish`, including unpublishing and archiving a published product.
 93: - `cost_price` is only visible to users with the `products.view_cost` permission.
 94: - `DELETE /products/{id}` — soft-deletes the product and its variants.
 95: - `supplier_id` is accepted as a positive integer but is **not** checked against any table yet —
 96:   the suppliers foreign key arrives in a later phase, and existing values must be audited/cleaned
 97:   before that FK migration can run.
 98: - List filters are validated: a malformed or unknown filter value (e.g. `category_id=abc` or a
 99:   non-existent category) returns 422, and non-numeric ids in paths return 404. Search is
100:   case-insensitive and treats `%`/`_` literally.
101: - New media files use UUID paths (`/storage/{uuid}/...`). Existing files at numeric paths
102:   remain readable and deletable without moving files. These are public URLs; UUIDs do not
103:   provide authorization for private assets.
104: 
105: ## Product Variants (`/api/v1/admin/products/{product}/variants`)
106: 
107: - Nested and scoped: a variant id under the wrong product returns 404.
108: - `GET` returns all variants without pagination. Create/update/delete require `products.update`
109:   (editing variants is editing the product); read requires `products.view`.
110: - The combination (color_name_en, size, capacity) must be unique per product — duplicates return 422.
111: - A variant without `sku` gets `{product_code}-{NN}` (e.g. `P00001-01`); without `barcode` it gets
112:   an internal EAN-13 barcode (prefix `2`).
113: - The last active variant of a published product cannot be deleted or deactivated (422).
114: - Sending `cost_price` without the `products.view_cost` permission is silently ignored on write.
115:   This also applies to nested variants when creating a product.
116: - Manual barcodes matching `2` followed by 12 digits are reserved for system generation.
117:   Updating a variant may resend its own current generated barcode.
118: - Prices accept at most two decimal places; excess precision returns 422. Empty barcode on update regenerates the internal barcode.
119: - Slugs use lowercase ASCII, and SKUs use uppercase ASCII. Uniqueness also checks legacy mixed-case values and soft-deleted records.
120: - Color combinations compare English color name, size and capacity without case sensitivity.
121:   English color name is required when Arabic color name or hex is supplied. Partial updates
122:   can retain the existing English name, but cannot clear it while other color details remain.
123: 
124: ## Product Media (`/api/v1/admin/products/{product}/media`)
125: 
126: - `GET` lists the product's media **and** its variants' media ordered by `order_column`
127:   (variant media items carry `variant_id`).
128: - `POST` with `collection=images` + `files[]` (max 10, jpg/png/webp, 5MB each), optionally with
129:   `variant_id` to attach the images to a variant instead. With `collection=video` + `file`
130:   (mp4/webm/quicktime, 50MB) — video is product-only; sending it with `variant_id` returns 422.
131: - `PUT /media/reorder` with `ids: [...]` in the desired order. Media of soft-deleted variants is excluded from listing, reorder, and delete.
132: - `DELETE /media/{media}` — the last image of a published product cannot be deleted (422).
133: - Originals and conversions from failed uploads are removed on rollback. Replacing or deleting
134:   existing media removes its files only after the database transaction commits.
135: - Images have a maximum width and height of 6000 pixels. Batch limits: 100 nested variants,
136:   500 category reorder items, 200 media reorder ids, and 10 uploaded images. Oversized batches
137:   are rejected before per-item validation queries. Reorder ids must be distinct.
138: - Published product edits and variant mutations recheck publishability inside a product lock.
139:   To remove a required price, change the product to draft first. Category deactivation is
140:   rejected while that category or a descendant contains published products.
141: - Invalid pagination (`per_page < 1`) returns 422; values above 100 are capped at 100.
142:   Catalog path ids accept 1–18 digits; malformed or oversized path ids return 404.
143: 
144: ### Updating with a file upload (important)
145: 
146: PHP does not parse uploaded files from `multipart/form-data` when the request method is `PUT`.
147: Therefore, to update a category (or any resource) **with an image**, the frontend must send a
148: `POST` request to `/categories/{id}` with `_method=PUT` included in the form body.
149: Laravel converts it to a `PUT` request automatically (method spoofing), and validation,
150: authorization and file handling then work as expected.
151: 
152: ### Existing media layout maintenance
153: 
154: Run php artisan media:backfill-path-layouts once for existing uploads. It persists numeric/UUID layout markers without moving or deleting files, so future URL generation does not probe remote storage. The command is idempotent.
155: 
156: ## المخزون والتحويلات والجرد (المرحلة 3)
157: 
158: قاعدة صارمة: أرصدة المخزون لا تُعدَّل إلا عبر `InventoryService::recordMovement` — حركة دفتر أولًا ثم تحديث الرصيد، في نفس الـ transaction. `available = on_hand - reserved - damaged`.
159: 
160: | المسار | الصلاحية | الوصف |
161: |---|---|---|
162: | `GET /inventory` | `inventory.view` | أرصدة حالية (فلاتر: branch_id, location_id, product_id, product_variant_id, low_stock=1) |
163: | `GET /inventory/movements` | `inventory.view` | دفتر الحركات من الأحدث (فلاتر: branch/product/type/from_date/to_date) |
164: | `POST /inventory/adjustments` | `inventory.adjust` | تسوية يدوية: items[{product_variant_id, adjustment_type: increase\|decrease\|mark_damaged, quantity, reason}] — الكل في transaction واحدة |
165: | `CRUD /transfers` | `transfers.*` | تحويلات بين الفروع (التعديل/الحذف للمسودة والملغي فقط) |
166: | `POST /transfers/{id}/approve` | `transfers.approve` | اعتماد + حجز الكميات عند المرسل (اختياري: items[{id, approved_qty}]) |
167: | `POST /transfers/{id}/ship` | `transfers.ship` | فك الحجز + إخراج فعلي + in_transit عند المستلم (اختياري: items[{id, shipped_qty}]) |
168: | `POST /transfers/{id}/receive` | `transfers.receive` | استلام: تسوية in_transit وإضافة المستلم؛ العجز يُسجَّل حركة adjustment_out موثقة + في الملاحظات (اختياري: items[{id, received_qty}]) |
169: | `POST /transfers/{id}/cancel` | `transfers.update` | إلغاء (المسودة مباشرة، والمعتمد بعد فك الحجز، والمشحون لا يُلغى) |
170: | `CRUD /stocktakes` | `stocktakes.*` | جلسات جرد — system_qty لقطة تلقائية وdifference محسوب في القاعدة |
171: | `POST /stocktakes/{id}/approve` | `stocktakes.approve` | اعتماد: فروق الجرد تتحول لحركات stocktake_gain/stocktake_loss وتتقفل الجلسة |
172: 
173: ملاحظات:
174: - سجل `stock_movements` غير قابل للتعديل أو الحذف برمجيًا وبنيويًا (بدون updated_at).
175: - جرد بموقع (location_id) نطاقه هو صف ذلك الموقع فقط؛ من غير موقع نطاقه صف "بدون موقع".
176: - ترقيم المستندات من الإعدادات: الحركات `MOV-`، التحويلات `TRF-`، الجرد `STK-`.
177: 
178: ## التسعير ومجموعات العملاء (المرحلة 4)
179: 
180: محرك التسعير `PricingService::resolve(variant, customer?, qty, branchId?)` يطبق شجرة أولويات: سعر خاص بالعميل ← سعر مجموعته ← قائمة نوعه (wholesale/distributor للمعتمدين فقط، وإلا retail) ← قائمة retail عند غياب سعر قناة الجملة ← `retail_price` الأساسي. خصم المجموعة يُطبَّق فوق سعر القناة أو الأساسي، ولا يُضاف إلى السعر الخاص بالعميل أو سعر قائمة مجموعته. غياب السعر الأساسي والقوائم المطابقة يرجع 422. داخل كل مستوى: قائمة الفرع المخصص أولًا، ثم أعلى شريحة كمية محققة، ثم priority، ثم السعر الأقل.
181: 
182: | المسار | الصلاحية | الوصف |
183: |---|---|---|
184: | `CRUD /customer-groups` | `customer_groups.*` | مجموعات عملاء (الحذف ممنوع مع عملاء أو قوائم مرتبطة) |
185: | `CRUD /price-lists` | `price_lists.*` | قوائم أسعار — النوع customer_specific يتطلب customer_id، وcustomer_group يتطلب customer_group_id، وغير مسموح بمالك لأي نوع آخر |
186: | `CRUD /price-lists/{id}/items` | `price_lists.*` | شرائح كميات — ممنوع تكرار (variant + min_qty) في نفس القائمة |
187: | `POST /price-lists/{id}/import` | `price_lists.import` | استيراد CSV (أعمدة التصدير نفسها) بـ upsert على دفعات، ويرجع تقرير created/updated/skipped/errors |
188: | `GET /price-lists/{id}/export` | `price_lists.export` | تصدير CSV: sku, variant_id, product_name, min_qty, price, starts_at, ends_at |
189: 
190: ## تحديثات مراجعة الجودة (جولة 3)
191: 
192: - **لقطة الجرد (C1):** `system_qty` تُؤخذ عند تسجيل `counted_qty` أو تغييره فقط؛ إعادة الحفظ بنفس الأعداد لا تجددها. لتجديد لقطة صنف صراحة أرسل `recount: true` مع عنصره في تحديث الجرد. اعتماد جرد فيه أصناف تغيّر رصيدها بعد العد يرجع 422 مع `errors.recount_item_ids` و`errors.recount_variant_ids` (الأصناف المحتاجة إعادة عد فقط).
193: - **نطاق الفروع (H1):** الوصول لكل الفروع امتياز صريح: دور Super Admin أو صلاحية `inventory.all_branches`. موظف بلا فرع وبلا الامتياز يُرفض (403) في كل عمليات المخزون/التحويلات/الجرد بدل رؤية كل الفروع.
194: - **عدم تكرار التسويات (H2):** `POST /inventory/adjustments` يقبل ترويسة `Idempotency-Key` (حتى 128 حرفًا). نفس المفتاح ونفس الحمولة يعيدان رد أول تنفيذ بلا حركات جديدة، ونفس المفتاح بحمولة مختلفة يرجع 409.
195: - **خصم المجموعة (H3):** `discount_percentage` يُطبق فوق سعر القناة (قائمة النوع إن وُجدت وإلا السعر الأساسي)، ولا يُخصم من سعر خاص بالعميل أو سعر قائمة المجموعة نفسها.
196: - **صنف غير مُسعَّر (M3):** متغير بلا `retail_price` ولا قائمة مطابقة يرمي 422 «الصنف غير مُسعَّر» من محرك التسعير بدل سعر صفر.
197: - **حمولات التحويل (M1):** أفعال الاعتماد/الشحن/الاستلام ترفض 409 أي معرّف عنصر لا يتبع التحويل وقت التنفيذ، وتقبل `expected_updated_at` اختياريًا (409 عند اختلافه عن آخر تعديل فعلي).
198: - **حذف التحويلات (M2):** ممنوع حذف تحويل له حركات في دفتر المخزون (مثل معتمد ثم ملغي)؛ الإلغاء هو الحفظ الصحيح لأثر التدقيق.
199: 
200: ## تحديثات مراجعة الجودة (جولة 4)
201: 
202: - **نطاق قوائم الأسعار (M4):** الموظف المقيد بفرع لا يرى ولا يعدّل إلا قوائم فرعه (`branch_id` = فرعه)؛ القوائم العامة وقوائم الفروع الأخرى خارج نطاقه (404)، وإنشاء قائمة يربطها بفرعه تلقائيًا. مجموعات العملاء كيان مركزي؛ تعديلها أو إنشاؤها أو حذفها يتطلب Super Admin أو `inventory.all_branches` بالإضافة إلى صلاحية العملية.
203: - **ترتيب شرائح الأسعار (L8):** داخل مستوى التسعير الواحد، قائمة الفرع المخصص تتقدم على الشريحة العامة الأعلى كمية — هذا مقصود بالتصميم (خصوصية الفرع قبل شريحة الكمية).
204: - **رصيد المعطّلات (M5):** تعطيل متغير/موقع لا يحبس رصيده: عمليات الإخراج وتخفيض الجرد والتحويل الصادر تعمل على المعطّل. كل إدخال فعلي موجب يتطلب متغيرًا غير محذوف وموقعًا نشطين، بما فيه زيادة الجرد واستلام التحويل.
205: - **حد إعادة الطلب (M6):** الحد الفعّال = `COALESCE(NULLIF(stock_levels.reorder_level, 0), product_variants.reorder_level, 0)` في فلتر `low_stock` وحقل `is_low_stock`.
206: - **تكلفة الحركات (M7):** `unit_cost` في ردود الحركات لا يظهر إلا بصلاحية `inventory.view_cost`.
207: - **التواريخ (M8):** التخزين UTC دائمًا. التواريخ المُدخلة (API وCSV) تُقبل بصيغ صارمة فقط (Y-m-d، Y-m-d H:i:s، ISO-8601 مع إزاحة) وتُفسَّر القيم بلا إزاحة بمنطقة العمل `BUSINESS_TIMEZONE` (افتراضي Africa/Cairo). فلاتر `from_date`/`to_date` للحركات بحدود أيام العمل. تصدير CSV يكتب التواريخ بصيغة ISO-8601 مع إزاحة لضمان إعادة استيراد بلا انزياح.
208: - **العملة (M9):** `price_lists.currency` مقصورة على EGP حاليًا (validation + قيد CHECK) حتى دعم تعدد العملات فعليًا في المحرك.
209: - **ترقيم الحركات (M10):** `GET /inventory/movements` يستخدم cursor pagination بلا COUNT أو OFFSET؛ استخدم `meta.next_cursor` أو `links.next` للتنقل، ولا تعتمد على إجمالي الصفوف أو أرقام الصفحات.
210: - **قيود قاعدة البيانات (M12):** ‏0 ≤ received ≤ shipped ≤ approved ≤ requested على عناصر التحويل، ومنع تكرار سطر التحويل (نفس الصنف والموقعين) أو صنف الجرد داخل الجلسة، وعدّ الجرد لا يكون سالبًا — كلها قيود قاعدة (تتطلب PostgreSQL 15+ لخاصية NULLS NOT DISTINCT).
211: - **مراجع الدفتر (L5):** `reference_type` يُخزَّن بأسماء قصيرة عبر morph map (`stock_transfer`, `stocktake`)؛ الصفوف القديمة باسم الكلاس الكامل تظل مقروءة.
212: - **أقفال المخزون (L6):** انتظار القفل محدود بـ 5 ثوانٍ لكل معاملة؛ التنافس الأطول يرجع 409 «المخزون مشغول» بدل تعليق الطلب.
213: 
214: ## تحديثات مراجعة الجودة (جولة 5)
215: 
216: - **إغلاق تصعيد قوائم الفرع (C-1):** موظف الفرع لا يستطيع تحويل قائمته لقائمة عامة بأي قيمة `branch_id` غير فرعه — بما فيها `null` صراحة (403، والقائمة لا تتغير). فحوص الوصول لقوائم الأسعار تُعاد على الصف المقفول داخل المعاملة، وقوائم خارج النطاق ترجع 404 موحدًا في كل العمليات.
217: - **تزامن التحويلات (H-1):** كل تعديل يرفع `version`، بما فيه استبدال البنود وحده وفي نفس الثانية. أرسل `expected_version` من آخر رد مع الاعتماد/الشحن/الاستلام؛ اختلافه يرجع 409 مع `errors.current_version`. يدعم `expected_updated_at` أيضًا بمقارنة اللحظة الزمنية، وطابعه يتقدم على الأقل ثانية عند كل تعديل لحماية العملاء القدامى. الحقلان اختياريان للتوافق، لكن أي عميل ينفذ مراجعة ثم اعتمادًا يجب أن يرسل أحدهما؛ من دونهما يُنفَّذ على أحدث نسخة مقفولة.
218: - **سقوط قنوات الجملة (M-1):** عميل الجملة/الموزع الذي لا يوجد له عنصر في قائمة قناته يُسعَّر من قوائم retail النشطة قبل الرجوع للسعر الأساسي — لا يدفع أكثر من عميل التجزئة لمجرد غياب قائمة قناته.
219: - **ازدحام الأقفال (M-2):** أخطاء انتظار القفل (55P03) و deadlock ‏(40P01) في مسارات المخزون ترجع 409 «المخزون مشغول» لا 500.
220: - **تحديث جزئي لعناصر الجرد (M-4):** ‏`PATCH /stocktakes/{stocktake}/items` يحدّث/ينشئ العناصر المرسلة فقط دون حذف الغائبة (نفس قواعد اللقطة: التحديث مرتبط بتغيّر العد أو `recount`)، فيمكن تسجيل العد صنفًا صنفًا وبناء جلسات أكبر من حد الاستبدال الكامل (500).
221: - **سياسة اعتماد الجرد (M-5):** قابلة للضبط عبر `STOCKTAKE_STALE_POLICY`: الافتراضي `reject` يرفض أي حركة على الرصيد الفعلي بعد لقطة العد مع `recount_item_ids`/`recount_variant_ids`. الوضع الاختياري `apply_difference` يطبق الفرق على الرصيد الحالي ويحفظ المبيعات والحركات البينية. الوضعان يرفضان تسوية جرد أخرى بعد اللقطة لمنع تكرار نفس العجز في جلسات متداخلة. اللقطة ورقم آخر حركة يُقرآن تحت قفل الأرصدة. فحص المحجوز والتالف يُطبق على الرصيد النهائي المتوقع.
222: - **ترقيم الحركات بالمؤشر (M-7):** ‏`GET /inventory/movements` يستخدم cursor pagination — الرد فيه `meta.next_cursor` و`links.next` بلا `total`، والتجوال عبر `?cursor=...`. لا يمكن القفز لرقم صفحة محدد.
223: - **مطابقة الدفتر (M-8):** أمر `php artisan inventory:reconcile` (خيار `--branch_id=`) يقارن كل رصيد في `stock_levels` بآخر `balance_after` في الدفتر لكل وعاء، ويتحقق من اتصال تسلسل الأرصدة، ويرجع كود فشل عند أي فرق — يُجدول دوريًا لكشف أي كتابة مباشرة على الأرصدة.
224: - **حذف متغير/منتج له رصيد (M-9):** ممنوع (422) — الحذف الناعم كان يحبس الرصيد. أرصدة قديمة محبوسة على متغيرات محذوفة (قبل هذا الحارس) يمكن تصفيتها بعمليات الإخراج، والإدخال عليها ممنوع.
225: - **عدم تكرار إنشاء التحويلات والجرد (L-7):** ‏`POST /transfers` و`POST /stocktakes` يقبلان `Idempotency-Key` مثل التسويات: إعادة المحاولة بنفس المفتاح والحمولة تعيد النموذج المنشأ، ونفس المفتاح بحمولة مختلفة 409. بصمة الحمولة تطابق الصور الرقمية المختلفة ("5" = 5 = 5.0). أمر `inventory:prune-idempotency-keys` يحذف المفاتيح الأقدم من 7 أيام (يُجدول يوميًا).
226: - **استيراد CSV (L-5/M-6):** الكتابة مجمّعة (upsert على دفعات) بدل صف بصف؛ مطابقة SKU لا حساسة لحالة الأحرف؛ وفشل التصدير أثناء البث يُسجَّل في السجلات.
227: - **مخزون منخفض (L-4):** الصفوف بلا حد إعادة طلب فعّال (> 0) لا تظهر في فلتر `low_stock` ولا تُعلَّم `is_low_stock` — صفوف صفرية ينشئها قفل المخزون كأثر جانبي ليست إنذارات.
228: - **نشاط الإدخال (L-3):** الحارس مركزي في `InventoryService`؛ زيادة الجرد واستلام التحويل يخضعان لنفس شرط نشاط المتغير والموقع. فشل الاستلام يتراجع عن فك رصيد الطريق وكل حركاته في المعاملة نفسها.
229: 
230: ## إغلاق المراجعة وتشغيلها
231: 
232: - شغّل `php artisan migrate --force` عند النشر. يتطلب المخزون PostgreSQL 15 أو أحدث. الترحيل الأخير يضيف نسخة التحويل، رقم حركة لقطة الجرد، وفهرس تنظيف مفاتيح التكرار ودالة ترقيم متزامنة. جلسات الجرد القديمة ذات لقطة بلا رقم حركة تحتاج إعادة عد (`recount: true`) عند رفض الاعتماد.
233: - حسابات المكتب الرئيسي التي ليست Super Admin تحتاج منح `inventory.all_branches` صراحة. `inventory.view_cost` مستقلة؛ ترحيل الصلاحيات لا يمنح امتيازات تلقائية للموظفين.
234: - إرسال `Idempotency-Key` ثابت لنفس المحاولة مطلوب من أي عميل ينفذ retries للتسويات أو إنشاء تحويل/جرد. بعد تغيير الحمولة استخدم مفتاحًا جديدًا. المفتاح اختياري في عقد API الحالي؛ الطلب بلا مفتاح عملية جديدة. ملفات خدمات المخزون بالواجهة ما زالت scaffolds؛ لا توجد فيها دورة إرسال فعلية لتعديلها بعد.
235: - إعادة الشحن أو الاستلام المكتملين تعيد الحالة والكميات المحفوظة بلا حركات جديدة. إرسال كميات مختلفة لنفس المرحلة المكتملة يرجع 409. صلاحيات الفرع تُفحص أيضًا عند إعادة الردود المحفوظة.
236: - مطابقة الدفتر مجدولة 02:00 والتنظيف 03:00 بتوقيت العمل. يجب تشغيل Laravel scheduler (`php artisan schedule:run` كل دقيقة، أو `schedule:work` للتطوير). فشل المطابقة أو المهمة يسجل خطأ للتنبيه عبر نظام مراقبة السجلات. المطابقة تستخدم لقطة SQL واحدة، وتكشف انقطاع التسلسل وصفوف الأرصدة المحذوفة أيضًا، وتعرض عينة محدودة من الفروق.
237: - تصدير CSV يعيد `X-Row-Count` لتمكين العميل من اكتشاف الملف المبتور؛ أخطاء البث مسجلة. التواريخ ISO المعادة من API (بما فيها Z والكسور) قابلة لإعادة الإرسال، والتاريخ بلا وقت يبدأ عند منتصف ليل منطقة العمل.
238: - ترقيم الحركات لا يستخدم `ALTER SEQUENCE` في التطبيق؛ قفل قصير داخل دالة قاعدة البيانات ينسق تخصيص الرقم ورفع الحد الأدنى، ويُفك قبل انتهاء معاملة المخزون. يتطلب مستخدم التطبيق USAGE وSELECT وUPDATE على التسلسل وEXECUTE على الدالة، ولا يتطلب ملكية التسلسل.
239: - قرارات السياسة الحالية محفوظة: قائمة الفرع تتقدم على الشريحة العامة؛ خصم المجموعة فوق سعر القناة؛ القناة الصريحة تتقدم على retail حتى لو كانت أعلى سعرًا؛ لا فرض لفصل المنشئ عن المعتمد؛ العنصر الغائب في حمولة المرحلة يستخدم كامل كميته الافتراضية. نقل المواقع داخل نفس الفرع غير مدعوم ضمن هذا المسار. تكلفة الحركة هي تكلفة الكتالوج الحالية، وليست متوسط تكلفة محاسبيًا.
240: 
241: ## المرحلة 5: العملاء ومصادقة المتجر واعتماد الجملة
242: 
243: ثلاث قنوات على جدول `customers` واحد: المتجر (`api/v1/store`) والجملة (`api/v1/wholesale`) والإدارة (`api/v1/admin`).
244: 
245: ### مصادقة المتجر القطاعي
246: 
247: التسجيل العام يبدأ بإثبات ملكية المحمول: `POST /store/auth/phone-verification/send` مع `phone` ثم `POST /store/auth/phone-verification/verify` مع `phone` و`code` (ستة أرقام). الرد الثاني يرجع `phone_verification_token` يُرسل مع تسجيل القطاعي أو الجملة. الرمز صالح عشر دقائق وله خمس محاولات، والإثبات صالح عشر دقائق ومربوط بالرقم ويُستهلك مرة واحدة. `CUSTOMER_REQUIRE_PHONE_VERIFICATION=true` افتراضيًا؛ لا يُعطَّل في الإنتاج. الحسابات السابقة لا تُعتبر موثقة تلقائيًا.
248: 
249: المحمول المصري يُحفظ بصيغة محلية `01[0125]xxxxxxxx`، مع توحيد `+20` و`0020` والأرقام العربية والفارسية والمسافات. الدخول يفصل البريد عن الهاتف صراحةً. التسجيل القطاعي والجملة يتشاركان حدًا قابلًا للضبط: افتراضيًا 20 طلبًا/دقيقة و500 طلب/24 ساعة لكل IP، مراعاةً لشبكات CGNAT. طلبات إرسال OTP محدودة أيضًا، ولا يُرسل أكثر من خمس رسائل تحقق للرقم يوميًا.
250: 
251: - `POST /store/auth/register` {name, phone*, email?, password(min 8)} — يُنشئ عميلًا `retail/approved` دائمًا (أي type/status في الطلب يُتجاهل) ويرجع 201 مع `token` (تسجيل دخول تلقائي).
252: - `POST /store/auth/login` {login (بريد أو هاتف), password} — الحساب الموقوف يرجع 403 مع سبب الإيقاف؛ بيانات خاطئة 401. حد محاولات: 5/دقيقة و30/ساعة و100/يوم للمُعرّف، و120/دقيقة للـ IP افتراضيًا؛ الحدود الطويلة وحدود IP قابلة للضبط.
253: - `POST /store/auth/logout` (auth:sanctum + auth.customer) — يحذف التوكن الحالي فقط.
254: - `POST /store/auth/forgot-password` {email أو phone، واحد فقط} — يضع نفس مهمة الطابور للحساب المعروف وغير المعروف. العامل يولّد رمزًا مُجزّأ بمفتاح `customer:{id}` في `password_reset_tokens` ويرسله عبر القناة المطلوبة (mail للبريد، SMS للهاتف)، ويستبعد الحساب الموقوف، مع مهلة 60 ثانية بين الإرسالات. الرد واحد دائمًا حتى لا يُستدل على وجود الحساب.
255: - `POST /store/auth/reset-password` {email أو phone، token (64 حرفًا)، password، password_confirmation} — صلاحية الرمز 60 دقيقة؛ يُستهلك مرة واحدة داخل معاملة، مع تغيير كلمة المرور وإلغاء جميع جلسات العميل. الرمز غير الصالح/المنتهي أو الحساب الموقوف يرجع 422.
256: - طلب الاستعادة محدود حسب IP والمعرّف الموحّد معًا. حد الإرسال داخل العامل خمس رسائل لكل حساب في اليوم بتوقيت العمل، عبر البريد والهاتف معًا، ومهلة دقيقة بين الإرسالات. تأكيد reset-password له حد مستقل. مهام الاستعادة والتحقق تُشفّر في `jobs` و`failed_jobs` بواسطة مفتاح التطبيق.
257: - `CUSTOMER_MAX_TOKENS=10`: إصدار توكن جديد ينظف المنتهي ويزيل أقدم جلسة تتجاوز الحد. `SANCTUM_TRACK_LAST_USED=false` يمنع كتابة `last_used_at` مع كل تصفح؛ يمكن تفعيله إذا كانت تتبعات الاستخدام مطلوبة.
258: - التشغيل: اضبط مزود البريد و`CUSTOMER_SMS_URL`/`CUSTOMER_SMS_TOKEN` (HTTPS gateway يستقبل JSON `to` و`message` مع Bearer authentication). اتصال طابور الاستعادة `CUSTOMER_PASSWORD_RESET_QUEUE_CONNECTION=database` مستقل عن اتصال الطابور العام. شغّل `php artisan queue:work database` لمعالجة الطلبات؛ اتصال `sync` مخصص للاختبارات.
259: 
260: ### تسجيل الجملة ومتابعة الحالة
261: 
262: - `POST /wholesale/auth/register` (multipart) {name, phone*, email?, password, company_name*, tax_number*, commercial_register*, documents[]* (pdf/jpg/png ≤ 5MB للملف، حتى 5 ملفات), document_types[]? موازية} — يُنشئ حساب `wholesale/pending` ومستنداته في **تخزين خاص** `storage/app/private/customer_documents/{id}` (لا روابط عامة)، ويرجع توكنًا لمتابعة الحالة.
263: - `GET /wholesale/auth/application-status` (auth:sanctum + auth.customer، بدون wholesale.approved) — الحالة الحالية و`documents` و`rejected_documents`؛ الحساب المرفوض مسموح له بمتابعة السبب والخروج فقط، والحساب الموقوف يُرفض.
264: 
265: ### إدارة العملاء في لوحة الإدارة (صلاحيات customers.*)
266: 
267: - `GET /admin/customers` فلاتر: `type`, `status`, `customer_group_id`, `search` (اسم/هاتف/بريد/سجل تجاري/اسم الشركة/رقم ضريبي)، و`trashed=only` لعرض المحذوفين. البحث مدعوم بعمود مولّد وفهرس GIN من امتداد PostgreSQL `pg_trgm`.
268: - `POST /admin/customers` — الحالة الافتراضية حسب النوع (قطاعي approved، جملة/موزع pending) ما لم تُرسل صراحة.
269: - `GET /admin/customers/{id}` — مع `documents` (لكل مستند `download_url` محمي) و`customer_group` و`addresses`.
270: - `PUT /admin/customers/{id}` — تغيير `type` أو `status` ممنوع. إرسال `credit_limit` أو `customer_group_id` أثناء الإنشاء أو التعديل يتطلب `customers.approve` بالإضافة لصلاحية العملية. لا يمكن مسح بيانات الجملة الإلزامية لحساب جملة/موزع معتمد.
271: - تغيير كلمة المرور أو البريد أو الهاتف يتطلب `customers.approve` أيضًا لمنع تغيير وسيلة الاستعادة والاستيلاء على الحساب. تغيير بيانات الدخول يُنهي الجلسات، ويدوّر remember_token ويحذف رموز الاستعادة. الإيقاف والحذف يحذفان رموز الاستعادة كذلك.
272: - `DELETE /admin/customers/{id}` — حذف ناعم + إنهاء الجلسات. `POST /admin/customers/{id}/restore` بصلاحية `customers.delete` يستعيد الحساب بنفس نوعه وحالته وتاريخه؛ الاستعادة لا تعيد توكناته السابقة.
273: - `POST /admin/customers/{id}/approve` {customer_group_id?, credit_limit?, type?: wholesale|distributor، company_name?, tax_number?, commercial_register?} — بيانات الشركة والضريبة والسجل مطلوبة قبل اعتماد الجملة/الموزع، ويمكن استكمالها في نفس الطلب. يضبط `approved_by/approved_at` ويمسح أسباب الرفض/الإيقاف. اعتماد مكرر بنفس النوع يرجع 422، وترقية النوع تمر بنفس التحقق.
274: - `POST /admin/customers/{id}/reject` {reason*} — للطلبات `pending` فقط؛ الرفض **لا** يقتل توكن التاجر حتى يطّلع على السبب. إيقاف حساب معتمد يتم عبر suspend.
275: - `POST /admin/customers/{id}/suspend` {reason*} — يوقف الحساب و**يحذف كل توكناته فورًا**.
276: - `GET /admin/customers/{customer}/documents/{document}/download` — تنزيل مستند من التخزين الخاص (الربط مقيّد: مستند عميل آخر يرجع 404).
277: - `PATCH /admin/customers/{customer}/documents/{document}` {status: pending|verified|rejected} — مراجعة مستند بصلاحية `customers.approve` والربط المقيّد نفسه. تنزيل ملف مفقود يرجع 404 واسم التنزيل يُطهَّر.
278: - التنزيل يتطلب صلاحية مستقلة `customers.documents.view`؛ صلاحية عرض العملاء وحدها لا تتيح مستندات الهوية والضريبة. مراجعة المستندات تتطلب customers.approve وcustomers.documents.view معًا، والتنزيل يسجل في التدقيق. اعتماد غير القطاعي يحتاج مستندًا موثّقًا واحدًا على الأقل، مع توثيق كل المستندات المرفقة واكتمال بيانات الشركة والضريبة والسجل.
279: - جدول `customer_audit_logs` يسجل الموظف والوقت والعملية للإنشاء والتعديل والاعتماد والرفض والإيقاف والحذف والاستعادة ومراجعة المستندات وتغيير بيانات الدخول؛ لا يخزن كلمات مرور أو توكنات. المستندات تحمل `reviewed_by` و`reviewed_at`.
280: 
281: حالات العميل: `pending/approved/rejected/suspended` (حلت suspended محل blocked من المرحلة 1 في المرحلة 5). الهاتف فريد وإلزامي، والبريد اختياري وغير حساس لحالة الأحرف؛ يظل بيانات تواصل حتى توثيق الملكية (`email_verified_at`). التسجيل لا يحجز البريد غير الموثّق، ولا يسمح باستخدامه للدخول أو الاستعادة. الفهرس الفريد يطبق على العناوين الموثّقة فقط. لا يوجد مسار عام لتوثيق البريد في هذه المرحلة؛ الهاتف هو المعرّف المتاح للحسابات الجديدة، ولا تفترض الهجرة توثيق العناوين السابقة. البريد يُطبَّع إلى lowercase وتُحذف المسافات المحيطة بالهاتف والبريد. هوية المحذوف تبقى محجوزة لحسابه الأصلي ويمكن استعادته؛ لا يُنشأ حساب جديد بنفس الهوية.
282: 
283: ## المرحلة 6: واجهة المتجر للقراءة (Storefront Read APIs)
284: 
285: كل روابط التصفح عامة (بلا مصادقة). إن أرسل عميل معتمد Bearer Token تُحسب أسعاره الشخصية (خصم مجموعة/قائمة خاصة/قناة جملة)؛ بقية الحالات والزائر يرون أسعار القطاعي. المنتجات المعروضة منشورة، قناتها retail أو both، أقسامها وأسلافها نشطة، وعلامتها إن وجدت نشطة. `products.is_active` مولّد من حالة النشر، و«متغير نشط» = `is_active` مع استبعاد المحذوف ناعمًا.
286: 
287: - `GET /store/home` — رد مجمّع: `banners` (نشطة وداخل نافذتها الزمنية، بترتيب sort_order)، `latest_products` (أحدث 12)، `best_sellers` (بـ `sales_count`،‏ 12)، `discounted_products` (متغير بـ `compare_at_price > base_price` أو عنصر في قائمة أسعار سارية أرخص من الأساسي، 12). كاش `store_home_data` ‏300 ثانية يخزن **المعرّفات فقط** — الأسعار تُحسب لكل طلب فلا تتسرب بين العملاء.
288: - `GET /store/categories` — شجرة الأقسام النشطة (3 مستويات) مع `products_count` للمنشور فقط في كل عقدة.
289: - `products_count` يشمل منتجات الأبناء النشطين، و`direct_products_count` يحفظ عدد المنتجات المباشرة. روابط pagination تحتفظ بالفلاتر في المتجر والإدارة. `page` في كتالوج المتجر محدود بـ500.
290: - `GET /store/brands` — النشطة بترتيب sort_order ثم الاسم. `GET /store/cities` — مدن الشحن النشطة مع `shipping_cost`.
291: - `GET /store/products` — فلاتر: `category` (id أو slug، يشمل الفروع)، `brand` (id/slug أو مصفوفة `brand[]` باستعلام واحد)، `color` (اسم اللون عربي/إنجليزي)، `price_min/price_max` والترتيب بالسعر على **أقل سعر نهائي معروض للعميل**، `in_stock=1`، و`sort`: ‏`newest|best_selling|price_asc|price_desc`. غير المسعّر يظهر أخيرًا في ترتيبي السعر. الترقيم 20 للصفحة. البطاقة: `price` النهائي، `old_price` مرجع نسبة الخصم (الأكبر من السعر الأساسي وcompare_at_price عند وجود خصم)، و`discount_percentage` و`in_stock`؛ لا تظهر كميات المخزون الدقيقة للعامة، لا في البطاقة ولا في المتغيرات. أسعار المتغيرات تُحمّل مجمعة بقواعد PricingService نفسها ولا يُعاد الاستعلام لكل متغير.
292: - المتاح أونلاين داخليًا (`store_available`) = مجموع `available` ‏(on_hand − reserved − damaged) عبر **الفروع النشطة فقط**، باستعلام فرعي مجمّع واحد — مخزون فرع معطّل لا يُحتسب.
293: - `GET /store/products/{slug}` — المنشور فقط (غيره 404): الوصف والصور وكل متغير نشط بسعره النهائي و`old_price` ومتاحه وحالة توفره. متغير غير مُسعَّر يظهر بسعر null بدل كسر الصفحة.
294: - `GET /store/products/{slug}/similar` — حتى 8: نفس القسم الفرعي أولًا ثم نفس العلامة، والمتوفر مخزونيًا أولًا، ويستبعد المنتج نفسه وغير المنشور.
295: - جداول/حقول جديدة: `banners` ‏(link_type/product|category|brand|external|none، position/main_slider|middle_banner|popup، نافذة زمنية)، `products.sales_count` (يُحدَّث مع مبيعات الطلبات في مرحلة الطلبات)، `product_variants.compare_at_price`.
296: 
297: ## المرحلة 7: السلة والطلبات والتوزيع (الأساس + خدمة التوزيع)
298: 
299: - جداول: `carts` (cart_token uuid فريد للزائر + customer_id اختياري — دمج سلة الزائر عند الدخول يتم في طبقة السلة) و`cart_items` (قيد فريد: سلة + متغير)، و`orders` و`order_items` (لقطات اسم/‏SKU وسعر، وallocated_branch_id على البند لدعم تقسيم الطلب) و`order_status_histories` (changed_by morph: موظف/عميل/نظام).
300: - الطلب: `order_number` من SettingService (‏ORD- + بادئة/حشو الإعدادات)، `channel` ‏store|wholesale|pos|admin، حالة `App\Enums\OrderStatus` ‏(pending/confirmed/processing/shipped/delivered/cancelled/returned) بقيد CHECK، و`payment_method` ‏cod|card|wallet|bank_transfer|credit و`payment_status` ‏unpaid|paid|failed|refunded. المعادلة الإلزامية: grand_total = (subtotal − discount_amount) + shipping_cost + tax_amount. `coupon_id` و`city_id` بلا FK (الأول حتى مرحلة الكوبونات، والثاني لأن تراجع هجرة 5.1 يُسقط cities — الطلب يحتفظ بالمعرّف كمرجع تاريخي).
301: - قاعدة صارمة: أي تغيير حالة يمر عبر `OrderService::changeStatus()` فقط — تسجل التغيير في `order_status_histories` بنفس الـ transaction، وعند الانتقال إلى `confirmed` تطلق التوزيع والحجز تلقائيًا.
302: - `OrderAllocationService::allocate(order, forcedBranchId?, performedBy?)`: فرع مُجبر (يُتحقق من نشاطه وتغطيته) ← أول فرع نشط يغطي الطلب كاملًا (أولوية لفرع نفس مدينة العميل بمقارنة branches.city مع cities.name_ar) ← كل صنف من الفرع الأعلى متاحًا (الصنف كاملًا من فرع واحد). داخل الفرع قد يتوزع الصنف على مواقع متعددة (الأعلى متاحًا أولًا، والمواقع المعطّلة مستبعدة). الحجز بحركات reserve في الدفتر (reference: order) عبر InventoryService حصرًا؛ أي نقص يُلغي العملية كلها بلا حجز متسرب، وإعادة توزيع طلب مُوزّع تُرفض.
303: - `OrderService::createFromCart`: لقطات اسم/‏SKU/سعر من PricingService (الخصم التسعيري في بنود الطلب، وخصم الكوبون على مستوى الطلب)، شحن = cities.shipping_cost، ضريبة من الإعدادات (tax_enabled وdefault_tax_rate=14%، صفر عند التعطيل أو شمول الأسعار)، إفراغ السلة، وأول سجل حالة pending. `changeStatus` بآلة حالات صارمة (لا إلغاء بعد الشحن/التسليم): الشحن يفك الحجز ويخصم sale فعليًا من نفس صفوف الحجز ويزيد products.sales_count، وإلغاء confirmed/processing يفك الحجز. حركات العميل/النظام تُنسب تنفيذيًا لأول Super Admin (الدفتر يتطلب موظفًا).
304: - كوبونات: جدول `coupons` (code فريد، percentage|fixed، حد أدنى/أقصى خصم، حد استخدام ونافذة زمنية) و`CouponService::validateAndApply` — أساس فقط بلا CRUD إداري بعد.
305: - روابط المتجر: `GET|POST|PUT|DELETE /store/cart/items` (زائر بهيدر `X-Cart-Session` أو عميل بتوكن؛ الأسعار لحظية والكمية محكومة بمتاح المتجر)، `POST /store/cart/coupon`، `POST /store/checkout/shipping-options` (خيار قياسي بتكلفة المدينة)، `POST /store/checkout` (زائر/مسجل؛ payment_url = null لعدم ربط بوابة دفع بعد)، `GET /store/orders/{number}/track` (عام برقم هاتف الطلب للتحقق)، `GET /store/account/orders` و`POST /store/account/orders/{id}/cancel` (بـ auth.customer؛ إلغاء من pending/confirmed فقط). سلة الزائر تُدمج في سلة الحساب عند تسجيل الدخول أو إنشاء الحساب.
306: - روابط الإدارة (صلاحيات orders.view/update/allocate): `GET /admin/orders` (فلاتر حالة/فرع/دفع/تاريخ/بحث) و`GET /admin/orders/{id}` و`PATCH /admin/orders/{id}/status` (عبر changeStatus) و`POST /admin/orders/{id}/allocate` (تلقائي أو branch_id مُجبر؛ لطلب confirmed/processing فقط).
307: 
308: ## المرحلة 8: الشحن والعروض والكوبونات
309: 
310: - جداول الشحن: `shipping_companies` ‏(code فريد، api_credentials مشفرة بـ cast ولا تُعرض في أي رد — مؤشر has_api_credentials فقط)، `shipping_zones` + وسيط `shipping_zone_cities`، `shipping_rates` (سعر فريد شركة×منطقة: base_cost + free_shipping_threshold + cod_fee + أيام تقديرية)، و`shipments` (بوليصة: awb فريد، حالة ShipmentStatus، تكلفة، مبلغ COD، raw_response).
311: - إدارة (صلاحيات shipping.*): ‏CRUD ‏`shipping-companies|shipping-zones|shipping-rates` (المناطق تُزامن مدنها بـ city_ids).
312: - `POST /admin/orders/{order}/shipment` (صلاحية orders.update): ينشئ بوليصة عبر ShipmentService — تكلفتها من سعر الشركة لمنطقة مدينة الطلب (مجانية فوق حد السعر، وإلا تكلفة الطلب)، وCOD = إجمالي الطلب عند الدفع عند الاستلام، ورقم البوليصة داخلي بصيغة CODE- عشوائي ما لم يُمرّر — ثم يحول الطلب إلى shipped عبر OrderService (فك حجز + بيع). فشل الانتقال يُلغي البوليصة.
313: - العروض والكوبونات (صلاحيات promotions.* وcoupons.*): ‏CRUD ‏`promotions` (أنواع percentage_discount/fixed_discount/buy_x_get_y/free_shipping واستهداف all/categories/brands/variants بـ target_ids — تُدار وتُخزن حاليًا، وتطبيقها التلقائي عند الشراء خطوة لاحقة) وCRUD ‏`coupons`.
314: - ترقية الكوبونات فوق أساس 7.3: نوع `free_shipping` (يعفي من شحن المدينة عند الشراء ويُسجل المُعفى)، و`usage_limit_per_customer` (افتراضي 1، و0 = بلا حد فردي)، وجدول `coupon_usages` (كوبون/عميل/طلب/قيمة) يُكتب عند كل شراء مع تحديث used_count. خصم النسبة = min(subtotal × value/100, max_discount_amount). أكواد الكوبونات تُخزن بأحرف كبيرة دائمًا.
315: 
316: ## المرحلة 8.3: الويب هوكس وروابط منفصلة
317: 
318: - مجموعة `api/v1/webhooks` (name: webhooks.) في bootstrap/app.php بلا أي مصادقة — الحماية بالتوقيع:
319:   - `POST /webhooks/payment/{gateway}`: بوابات معرفة في config/webhooks.php (paymob/stripe/moyasar — سر HMAC من البيئة). توقيع HMAC-SHA256 لنص الطلب الخام في هيدر X-Webhook-Signature (قابل للضبط لكل بوابة). نجاح الدفع: payment_status=paid ثم تأكيد تلقائي للطلب pending عبر OrderService (حجز وتوزيع فوري).
320:   - `POST /webhooks/shipping/{company}`: السر من api_credentials.webhook_secret للشركة (أو api_key أو سر بيئة افتراضي). تُبحث البوليصة بـ awb_number؛ delivered تحوّل الطلب المشحون إلى delivered وتثبت دفع COD بـ payment_status=paid. مرادفات حالات الشركات الشائعة مدعومة (picked/collected/transit/rto...).
321: - كل طلب يُسجل أولًا في `webhook_logs` (provider, event_id, payload, signature_valid, status, error, ip) قبل المعالجة؛ حدث بنفس (provider, event_id) سبق معالجته يُعلَّم duplicate ولا تُعاد معالجته. توقيع فاسد = 403، بوابة/شركة غير معروفة = 404، أخطاء عمل (طلب/بوليصة غير موجودة) = 200 مع received=false لتفادي إعادة إرسال المزود.
322: - توفيق روابط مع النص الرسمي: تحديث/حذف بند السلة صار بـ {item} (معرّف البند يُعرض في رد السلة)، checkout اسمه checkout.store والمتحكم CheckoutController@store، وطلبات المتجر (تتبع/حساب/إلغاء) في Store\OrderController، واسم رابط حالة الأدمن orders.update-status.
323: ### التشغيل والحماية من الضغط
324: 
325: - قراءة الكتالوج محدودة افتراضيًا بـ600 طلب/دقيقة لكل IP، وطلبات فلترة/ترتيب السعر بـ20 طلبًا/دقيقة لكل IP و200 طلب/دقيقة للموقع كله. القيم قابلة للضبط من config/auth.php ومتغيرات STORE_*. الحدين يشتركان في ملفات المسارات العامة. فلترة السعر وترتيبه يستخدمان نتيجة `LEFT JOIN LATERAL` واحدة لكل منتج بدل تكرار تعبير السعر لكل شرط. عدّ paginate واستعلام البيانات منفصلان؛ ترتيب السعر دون حدود سعرية يستخدم count خاليًا من حساب الأسعار مع الحفاظ على إجمالي الصفحات؛ الترتيب بسعر شخصي يظل بحاجة إلى فحص خطة التنفيذ على حجم الإنتاج، والاختبارات لا تمثل اختبار ضغط لـ50 ألف منتج.
326: - كاش معرّفات الرئيسية يستخدم Cache::flexible: فترة جديدة 300 ثانية وفترة قديمة قابلة للعرض حتى 1800 ثانية، والتحديث المؤجّل تحت قفل؛ القفل المنتظر يستخدم فقط عند البداية الباردة. الأسعار الشخصية تُحسب لكل طلب، وتُرسل `Cache-Control: private, no-store` و`Vary: Authorization` للطلبات ذات التوكن.
327: - تقريب الأسعار في PHP يستخدم الحساب العشري الدقيق وHalfUp ليطابق تقريب PostgreSQL numeric. نسب الخصم الأقل من 1% بعد التقريب تُعرض null ويُستبعد المنتج من قسم التخفيضات.
328: - شغّل عامل الطابور السابق وLaravel Scheduler (`php artisan schedule:run` كل دقيقة عبر مشغّل النظام). الجدولة تنظف توكنات Sanctum يوميًا، والوظائف الفاشلة الأقدم من أسبوع، وملفات staging الأقدم من ساعة والتحديات المنتهية دوريًا. `queue:monitor` يعمل كل خمس دقائق ويكتب خطأ في السجل عند تجاوز عمق الطابور 100؛ اربط سجلات التشغيل بنظام التنبيه المستخدم عند النشر.
329: - اضبط حدود حجم جسم الطلب ووقت الرفع في خادم الويب وPHP؛ حدود Laravel تمنع التخزين وإنشاء الحسابات بعد تجاوز المعدل، لكنها لا تمنع وصول جسم الرفع إلى خادم الويب نفسه.
330: 
331: ### ترحيل البيانات القائمة
332: 
333: الهجرات القديمة التي تضيف أعمدة مولّدة مخزّنة (`112512_add_storefront_active_flag_to_products` و`115322_normalize_customer_identity`) قد تعيد كتابة الجداول. تطبيقها محليًا على بيانات صغيرة لا يثبت صلاحيتها للنشر دون توقف على جداول كبيرة؛ إن لم تُطبّق بالإنتاج بعد، تحتاج نافذة صيانة أو خطة backfill على دفعات وفهارس CONCURRENTLY قبل تشغيلها. لا تُعِد تشغيل هجرة سبق تطبيقها. امتداد `pg_trgm` يجب أن يكون متاحًا ويُجهّزه مسؤول قاعدة البيانات إن لم يملك مستخدم التطبيق صلاحية إنشائه.
334: 
335: الهجرة الجديدة تستخدم `NOT VALID` لقيود المحمول والحد الائتماني وبيانات الجملة، فتمنع المخالفات الجديدة دون مسح شامل أثناء الإضافة؛ والافتراضي في القاعدة pending لجميع الإدخالات الخام، بينما النموذج يفرض approved للقطاعي. حذف فهرس البريد الزائد في هجرة مستقلة خارج المعاملة مع lock_timeout قصير، وتستبدل الهجرة 141204 فهرس LOWER(email) بفهرس فريد جزئي للبريد الموثّق، خارج المعاملة وبـ CONCURRENTLY. الرجوع عن هذه الهجرة يتطلب إزالة تعارضات البريد غير الموثّق قبل استعادة التفرد القديم.
336: 
337: افحص الهواتف القديمة بـ `php artisan customers:normalize-phones`، ثم `--apply` لتطبيق خطة خالية من التصادمات على دفعات. التصادمات أو الأرقام غير الصالحة تتطلب إصلاحًا يدويًا دون دمج حسابات آلي. بعد استكمال بيانات الجملة القديمة وتصحيح الائتمان شغّل `php artisan customers:validate-domains`. القيم `legacy-{id}` القديمة مسموحة كقيم انتقالية لكنها ليست أرقامًا قابلة لتسجيل الدخول أو الاستعادة. فشل اكتساب قفل الهجرة يستلزم إعادة المحاولة في وقت مناسب.
338: 
339: 
340: - ميزانية SMS الدائمة عالمية ولكل نافذة داخل معاملة claim نفسها: `CUSTOMER_SMS_HOURLY_LIMIT=100` و`CUSTOMER_SMS_DAILY_LIMIT=1000`، بالإضافة لميزانية المستلم. رسائل استعادة البريد لا تخصم من ميزانية SMS. الوصول إلى 80% يسجل warning تشغيليًا مرة لكل نافذة؛ عند استنفاد الميزانية تتوقف الرسائل حتى انتهاء النافذة. حد اليوم بتوقيت العمل، وحد الساعة ساعة تقويمية.
341: - كل حدود IP للعملاء قابلة للضبط عبر `auth.customer_limits`؛ لا تستبدل الميزانية الدائمة بحدود IP. إثبات الهاتف الساري لا يُلغى بطلب إرسال جديد. رموز الإثبات والاستعادة العشوائية تستخدم SHA-256 مع دعم التجزئات القديمة حتى انتهائها؛ OTP يظل محميًا بالتجزئة البطيئة والمحاولات المحدودة.
342: - عقد بوابة SMS: تستقبل HTTPS JSON `to` و`message` وتعيد 2xx مع `{"success":true}` عند القبول؛ `success=false` أو رد ناقص يعتبر فشلًا. مهام OTP والاستعادة لها محاولة واحدة وtimeout=30 ثانية. يسجل نجاح/فشل OTP لمتابعة نسبة الفشل؛ الإرسال الفاشل يحتفظ بحجز الميزانية احترازيًا لأن فشل الشبكة قد يأتي بعد قبول المزود، وإعادة الطلب تخضع للمهلة المعتادة.
343: - إعداد الإنتاج `TRUSTED_PROXIES` إلزامي: عناوين أو CIDRs الموازن الفعلية فقط، مثل `10.0.0.10,10.0.1.0/24`. استخدام `none` إقرار صريح بوصول الطلبات مباشرةً. `*` ممنوع في الإنتاج. يجب أن يستبدل الموازن رؤوس forwarding القادمة من العميل؛ لا تثق بقيم أرسلها العميل نفسه.
344: - تغيير `company_name/tax_number/commercial_register` يتطلب `customers.approve` ويسجل `business_identity_changed`. إنشاء العميل يقبل pending/approved فقط؛ اعتماد القطاعي يثبت approved_at. يسجل التدقيق أيضًا التسجيل الذاتي، الدخول الناجح والفاشل وإصدار التوكنات دون أسرار خام.
345: - التنظيف الدوري يزيل مجلدات المستندات النهائية اليتيمة بعد ساعة، ويحافظ على ملفات العملاء المحذوفين ناعمًا. تطبيع الهواتف يستخدم خطة مؤقتة في PostgreSQL وكشف التصادمات بـ GROUP BY ودفعات 500 بدل تحميل كل الهواتف في ذاكرة PHP. أخطاء VALIDATE CONSTRAINT غير 23514 لا تُعرض كأخطاء بيانات.
346: - المخزون السالب ممنوع أصلًا بقيد stock_levels_valid_balances (`on_hand >= reserved + damaged`)، لذلك لا يلزم تغيير معنى الجمع. النصوص العربية ورسائل SMS الأصلية محفوظة بصيغة UTF-8. لا يوجد مسار لإعادة تقديم طلب جملة مرفوض؛ الرقم يبقى محجوزًا، ويمكن للموظف متابعة معالجة الحساب الأصلي. `credit_limit/customer_group_id` في رد العميل الحالي مستمران كجزء من عقد حساب الجملة.
347: 
348: ## جولة مراجعة المرحلة 8: الأقفال والذرّية وحماية الدفع
349: 
350: - (C1) ‏OrderService::changeStatus وOrderAllocationService::allocate يعيدان قراءة الطلب بـ lockForUpdate داخل المعاملة — النسخ القديمة بيد المتصلين لا تُمرَّر، والانتقالات على نفس الطلب تتسلسل.
351: - (H1) ‏ShipmentService يقفل الطلب ويتحقق: الحالة Confirmed/Processing فقط، ولا بوليصة نشطة (غير failed/returned) — إعادة الشحن بعد فشل مسموحة بسياسة صريحة.
352: - (H2) ‏createFromCart يقفل صف السلة ويقرأ بنودها طازجة — نقرة مكررة تجد سلة فارغة (422) بدل طلب مكرر.
353: - (H3) عند الشراء يُقفل صف الكوبون حتى نهاية المعاملة (التحقق والعدّ والتسجيل ذرّية)، وحد العميل الواحد يُفرض على الزائر بهاتفه الموحد الصيغة (Customer::normalizePhone) عبر طلباته غير الملغاة — تبديل cart_token لا يتجاوزه. فحص السلة قبل الشراء للزائر يظل بالحد الكلي فقط (لا هاتف بعد).
354: - (H4) معالجة الويب هوك كلها داخل DB::transaction تبدأ بـ pg_advisory_xact_lock على (provider, event)، ومفتاح الحدث عند غياب معرّف حقيقي هو sha256 لجسم الطلب.
355: - (H5) حدث paid يُتحقق من مبلغه وعملته مقابل grand_total (مبالغ القروش تُقسم على 100) وعدم التطابق يُسجل amount mismatch بلا أي تغيير؛ لا رجوع من paid إلى failed؛ حدث Paymob المعلّق (pending=true) ليس فشلًا؛ دفع على طلب ملغي يُثبت الدفع ويرفع علم orders.requires_refund (يظهر في رد الأدمن) ولا يُحيي الطلب.
356: - (H6) مفتاح حدث الشحن: event_id حقيقي فقط (id الشحنة الثابت لا يصلح)، وإلا awb|status|timestamp، وإلا sha256. وحالات البوليصة مرتبة: لا تراجع في سلسلة created→picked_up→in_transit→out_for_delivery→delivered، والحالتان delivered/returned نهائيتان، والفشل قابل للاستئناف.
357: - (H7) هجرة فهارس للمفاتيح الساخنة: carts.customer_id، orders.customer_id/allocated_branch_id، order_items.order_id/product_variant_id/allocated_branch_id، shipments.order_id، coupon_usages.order_id.
358: - (H8) ‏DELETE /store/cart/coupon يزيل الكوبون، وفشل الكوبون عند إتمام الشراء يرجع 422 مع code=coupon_invalid في جسم الرد.
359: - (H9) طرق دفع المتجر من config/store.php ‏(STORE_PAYMENT_METHODS، الافتراضي cod فقط) — وcredit متاح برمجيًا لعملاء الجملة/التوزيع المعتمدين فقط، ولا تُفتح طريقة إلكترونية قبل ربط بوابتها.
360: - (H10) ‏reserveItemFromBranch يقفل صفوف الأرصدة بـ lockForUpdate وبترتيب id ثابت؛ وفحص canBranchFulfillFullOrder استشاري — الحارس النهائي هو إعادة تحقق recordMovement تحت قفله.
361: 
362: ## جولة تقوية المتجر والسلة والويب هوك (M1–M10)
363: 
364: - (M1) توسيع أعمدة shipping_address_line/shipping_notes/order_status_histories.notes/tracking_url_template إلى varchar(500) لتوافق تحقق max:500 — قيم 256–500 لم تعد تنهار 22001.
365: - (M2) ‏X-Cart-Session غير الـ UUID يُتجاهل، وتوكن أي سلة جديدة يُولّد على الخادم دائمًا.
366: - (M3) قراءة السلة (GET cart/items وخيارات الشحن) لا تحفظ صفًا — سلة فارغة افتراضية، والإنشاء عند أول إضافة. محددات مسماة: throttle:cart ‏(60/دقيقة)، checkout ‏(10/دقيقة)، order-tracking ‏(10/دقيقة)، webhooks ‏(120/دقيقة).
367: - (M4) التحقق من التوقيع قبل تخزين حمولة الويب هوك؛ الرفض يُسجل صفًا مختصرًا بلا payload؛ حد جسم 256KB (يرجع 413)؛ ‏webhooks:prune-logs مجدول يوميًا باحتفاظ 90 يومًا.
368: - (M5) تتبع الطلب: لا notes في السجل المعروض للعامة، ومقارنة الهاتف بصيغة موحدة الطرفين، وحد 10/دقيقة لكل IP.
369: - (M6) قيد فريد carts.customer_id ودمج سلة الزائر داخل transaction بقفل صف — لا سلال مكررة ولا كميات مضاعفة مع الطلبات المتوازية.
370: - (M7) أنماط رقمية لمعاملات item/order في المتجر وorder/coupon/promotion/shipping_* في الأدمن — غير الرقمي 404.
371: - (M8) ‏null صريح لحقول NOT NULL في الكوبونات/العروض يُحذف من حمولة الحفظ في المتحكم (الأعمدة القابلة للإفراغ فعلًا مثل min_order_amount تظل قابلة للتصفير).
372: - (M9) حذف شركة شحن لها بوليصات أو كوبون له استخدامات يرجع 422 (التعطيل هو البديل)، وحذف كوبون غير مستخدم يفك carts.coupon_id أولًا.
373: - (M10) تعديل شركة الشحن بـ api_credentials=null لا يمحو الأسرار، وسر توقيع الويب هوك هو webhook_secret الخاص بالشركة فقط — بلا رجوع api_key ولا سر افتراضي.
374: 
375: ## جولة آثار الطلب والمال (M11–M19 وL1–L6)
376: 
377: - (M11) تحصيل COD في ويب هوك الشحن يُثبت فقط مع انتقال فعلي Shipped → Delivered داخل نفس المعاملة؛ وحدث returned ينقل الطلب المشحون/المُسلَّم إلى Returned عبر بوابة الحالة.
378: - (M12) مصدر تسعير شحن العميل موحّد في ShippingQuoteService: أسعار المناطق (أول شركة نشطة لها سعر للمدينة) مع حد الشحن المجاني ورسوم COD (عمود orders.cod_fee)، ورجوع لسعر المدينة عند غياب سعر — وخيارات الشحن تعرض نفس التسعيرة. وrateFor صار join مباشرًا rates × zone_cities بالشركة. العروض ما زالت تُدار فقط: PromotionResource يعرض auto_applied=false صراحة.
379: - (M13) إلغاء الطلب يعكس استخدام الكوبون (حذف coupon_usages وإنقاص used_count) ويرفع requires_refund إن كان مدفوعًا. والإرجاع يسجل حركات sale_return معاكسة لحركات البيع وينقص sales_count، أو يترك ملاحظة «استلام يدوي» في السجل إن لم توجد حركات بيع.
380: - (M14) ‏createFromCart يعيد التحقق من قابلية كل بند للبيع (نشط/منشور/غير محذوف) بشكل مجمّع قبل إنشاء الطلب.
381: - (M15) ‏totals() يقبل بنودًا محسوبة مسبقًا (present وcreateFromCart يعيدان استخدامها)، وتغطية الفروع في التوزيع تُحسب باستعلام واحد مجمّع GROUP BY branch+variant وتُقرأ من الذاكرة.
382: - (M16) بحث الأدمن: رقم الطلب والهاتف بالبادئة، الاسم بالاحتواء مع تهريب %/_/\، والتواريخ بنطاق created_at (بداية يوم منطقة العمل → UTC) بدل whereDate.
383: - (M17) تقريب كل سطر أولًا ثم الجمع، وخصم الكوبون يوزَّع على البنود تناسبيًا (بنفس أسلوب الضريبة) فمجموع order_items.discount_amount يساوي خصم الطلب الكلي.
384: - (M18) قيمة الكوبون النسبي حدها 100%.
385: - (M19) «دُفع ولم يُؤكَّد»: ‏Log::warning + علم orders.needs_attention ظاهر في AdminOrderResource. وحركات النظام/العميل في الدفتر تُنسب لمستخدم نظام مخصص (system@alfarid.local، يُضبط بـ ORDER_SYSTEM_USER_EMAIL) بدل أول Super Admin.
386: - (L1) التوكن من هيدر X-Cart-Session فقط في كل المسارات (تحقق: لا قراءة من query/body). (L2) زيادة بند السلة بـ increment ذرّي. (L3) وضع Shipped من تحديث حالة الأدمن ممنوع — من إنشاء البوليصة فقط. (L4) ‏rawurlencode لرقم البوليصة في رابط التتبع. (L5) ‏branches.city_id اختياري وأولوية فرع مدينة العميل بالمعرّف أولًا ثم الاسم. (L6) ‏qty في السلة حدها 10000.
387: - (INFO) المُتحقق العام HMAC لا يطابق مخططات Paymob/Stripe الحقيقية ولا يحمل حماية replay — يُستكمل عند الربط الفعلي ببوابة بعينها، وحتى ذلك كل الأحداث الحقيقية من تلك البوابات ستُرفض التوقيع. والحجز عند التأكيد فقط قرار تصميمي واعٍ: طلبات COD المعلقة لا تحجز مخزونًا وقد يفشل تأكيدها عند نفاد الرصيد.
388: 
389: ## جولة الحجز المبكر والدفع (F-01–F-10)
390: 
391: - (F-01) الحجز صار داخل معاملة الشراء نفسها: ‏createFromCart يستدعي allocate بعد إنشاء البنود، فنقص الرصيد يُسقط الشراء كله بدل طلب معلّق غير قابل للتنفيذ — وإلغاء Pending بقى يفك الحجز أيضًا. وأمر مجدول orders:expire-pending (كل 15 دقيقة) يلغي المعلّقة المنتهية: إلكتروني غير مدفوع بعد ORDER_PENDING_ONLINE_EXPIRE_MINUTES (افتراضي 30) وCOD بعد ORDER_PENDING_COD_EXPIRE_HOURS (افتراضي 72).
392: - (F-02) ‏allocate يرتب البنود بـ product_variant_id قبل أي قفل — ترتيب قفل عام ثابت يمنع deadlock (40P01) بين طلبين متعاكسي البنود.
393: - (F-03) البيع بالقطعة: كميات السلة integer (1..10000، والتحديث 0..10000)، وأي سطر line_total <= 0 يُرفض عند الشراء.
394: - (F-04) ‏coupon_usages.guest_phone_normalized (مع فهرس وملء رجعي من هاتف الطلب): حد كوبون الزائر يُعدّ في SQL على العمود بدل مسح الاستخدامات في PHP أثناء قفل الكوبون.
395: - (F-05) الاسترداد يرفع needs_attention لأي طلب غير ملغي، وإنشاء البوليصة يرفض دفعًا مسبقًا (غير COD) حالته ليست paid — ضبط paid اليدوي للتحويل البنكي قبل الشحن مقصود.
396: - (F-06) أنماط تحقق حقيقية لكل بوابة (driver في config/webhooks.php): stripe بهيدر Stripe-Signature ‏(t/v1 وحداثة ≤ 300 ثانية)، وpaymob بـ HMAC-SHA512 لحقول المعاملة بترتيبها الرسمي من معامل query ‏hmac، وmoyasar بـ secret_token داخل الجسم. الافتراضي لباقي البوابات HMAC-SHA256 العام.
397: - (F-07) قبل التحقق مفتاح سجل الويب هوك هو sha256 للجسم فقط؛ وبعده تُنقّى المعرّفات (قيمة مفردة وحد 191 حرفًا). ومعاملات المسارات gateway/company مقيدة النمط والطول — لا 500 من حمولات مشوّهة.
398: - (F-08) مفتاح حدث الدفع = معرّف المعاملة + «:» + النتيجة (paid/refunded/…) فحدث الاسترداد لا يُبتلع كـ duplicate لحدث الدفع.
399: - (F-09) إضافات/تحديث/دمج بنود السلة صارت UPSERT ذرّيًا (ON CONFLICT DO UPDATE) — النقر المزدوج لم يعد يخرج 500 من قيد التفرد.
400: - (F-10) ‏accountCart يستخدم createOrFirst (savepoint داخل المعاملات) بدل firstOrCreate الذي كان يترك معاملة الدمج aborted (25P02).
401: 
402: ## جولة سلامة الطلب (F-11–F-17)
403: 
404: - (F-11) ‏changeStatus يقبل expectedFrom اختياريًا يُفحص بعد إعادة القراءة بقفل الصف؛ إلغاء العميل يمرر [Pending, Confirmed] — فانتقال أدمن متزامن إلى Processing يوقف الإلغاء بدل أن يمر من فحص على نسخة قديمة.
405: - (F-12) محلولة ببنية F-01: التوزيع عند الشراء نفسه هو فحص التوفر الموثوق (قيد فرع واحد لكل صنف)؛ فحص المجموع المبكر يبقى رسالة ودّية فقط ولا يُبنى عليه قرار.
406: - (F-13) شراء idempotent: هيدر Idempotency-Key اختياري يُحفظ في orders.idempotency_key (فريد)، وإعادة الإرسال بنفس المفتاح ترجع الطلب نفسه قبل لمس السلة.
407: - (F-14) الآثار المالية صارت مركزية في changeStatus: أي انتقال Delivered لطلب COD يضبط payment_status=paid (تسليم الأدمن اليدوي مثل الويب هوك)، وأي Returned لطلب مدفوع يرفع requires_refund.
408: - (F-15) إشعار مرتجع شركة الشحن (بما فيه rto) لا يعيد البضاعة للمخزون: يعلّم الطلب needs_attention فقط. الإعادة الفعلية عند استلام المستودع — الأدمن ينقل الطلب Returned عبر changeStatus فتُسجل sale_return عندها.
409: - (F-16) بوليصة فاشلة لم تعد طريقًا مسدودًا: حدث Failed يعلّم الطلب needs_attention، وطلب Shipped كل بوالصه فاشلة/مرتجعة يقبل بوليصة بديلة بلا changeStatus وبلا خصم مخزون ثانٍ.
410: - (F-17) سقف استخدامات الزوار المعلّقة لكل كوبون: ‏STORE_GUEST_COUPON_PENDING_CAP (افتراضي 20، و0 يعطّله) في assertRedeemable — تدوير أرقام غير مُتحققة لا يستنزف الحملة؛ والمعلّقة تُحسم بانتهاء الصلاحية (إلغاء يعكس الاستخدام).
411: 
412: ## المرحلة 9: إدارة المرتجعات والاسترداد المالي (Returns / RMA)
413: 
414: القاعدة الذهبية: إنشاء طلب المرتجع أو الموافقة المبدئية عليه لا يضيف أي رصيد للمخزون. الإضافة الفعلية تتم حصريًا في خطوة الاستلام (receive) بعد فحص كل قطعة، وعبر `InventoryService::recordMovement` فقط.
415: 
416: ### الجداول
417: 
418: - `return_requests`: ‏return_number فريد بصيغة `RET-001001` (ترقيم SettingService: ‏return_prefix/return_next_number=1001/return_padding=6)، وorder_id/customer_id (nullable)/branch_id (فرع الاستلام — يُحدد عند الاعتماد)، وstatus enum ‏(pending/approved/rejected/received/refunded/cancelled)، وrefund_method enum ‏(original_payment/wallet/bank_transfer/cash)، وtotal_refund_amount، وreason/admin_notes/refund_reference، وحقول approved_by/at وreceived_by/at وrefunded_by/at.
419: - `return_request_items`: ‏return_request_id (cascade) وorder_item_id وproduct_variant_id، وكميات requested/approved/received_good/received_damaged ‏(decimal 12,4)، وunit_refund_price = صافي ما دفعه العميل للوحدة بعد كل الخصومات (سعر البند × الكمية − discount_amount البند) ÷ الكمية، وitem_reason وattachments (مسارات صور العيوب على القرص العام `return_requests/{id}`).
420: - `customers.wallet_balance` ‏(decimal 12,2): رصيد محفظة العميل — لم يكن موجودًا قبل هذه المرحلة، والاسترداد بطريقة wallet يُضاف إليه.
421: - إعدادات: ‏`return_window_days` (افتراضي 14) في مجموعة orders — نافذة الاسترجاع من لحظة انتقال الطلب إلى delivered (آخر سجل حالة)، وتُزرع للقواعد القائمة بهجرة insertOrIgnore.
422: 
423: ### الخدمة (ReturnService)
424: 
425: - ‏`createReturnRequest`: الطلب يجب أن يكون Delivered وداخل نافذة الاسترجاع، ولكل بند: ‏requested + (مجموع requested في طلبات غير مرفوضة/ملغاة لنفس order_item) ≤ qty المشتراة. عند إنشاء العميل تُفرض ملكية الطلب (غير الموجود في حسابه = 404 من المتحكم).
426: - ‏`approve`: من pending فقط — يحدد branch_id والكميات المعتمدة (بند غير مذكور = كامل المطلوب؛ مجموع معتمد صفر = رفض الاعتماد). **لا أثر مخزني.**
427: - ‏`receive`: من approved فقط، والحمولة تغطي كل البنود، وgood + damaged ≤ approved لكل بند. داخل transaction: السليم بحركة `sale_return` على `on_hand`، والتالف بحركتين: `sale_return` على `on_hand` (عودة فيزيائية) ثم `damage` على `damaged` — لأن وعاء التالف شريحة من الرصيد الفعلي في نموذج المخزون الحالي، فإدخاله على damaged وحده كان سيكسر قاعدة «المتاح لا يصير سالبًا» عند انخفاض الرصيد. الحركات كلها بمرجع morph ‏`return_request` وعلى مستوى الفرع المستلم (location فارغ)، وعدّاد مبيعات المنتج يتراجع بالكمية المستلمة. يحسب total_refund_amount = Σ (المستلم × unit_refund_price).
428: - ‏`refund`: من received فقط. ‏wallet يضيف الإجمالي لرصيد محفظة العميل بقفل صف (طلبات الزوار بلا حساب تُرفض لهذه الطريقة)، وباقي الطرق تسجل refund_reference. عند اكتمال استلام كل بنود الطلب الأصلي ينقل `OrderService::changeStatus` الطلب إلى Returned بمعامل `returnEffects: false` — بلا إعادة مخزون ثانية (الاستلام سوّاها) وبلا علم requires_refund (الرد اكتمل داخل المرتجع). الإرجاع الجزئي يبقي الطلب Delivered.
429: - الرفض (من pending) والإلغاء (من pending/approved) عبر PATCH — بلا آثار، ويحرران سقف كميات البند لطلبات لاحقة. حذف مرتجع received/refunded ممنوع (422).
430: 
431: ### المسارات
432: 
433: - المتجر: ‏`POST /api/v1/store/account/returns` ‏(auth:sanctum + auth.customer) — order_id + reason + refund_method اختياري + items (order_item_id/requested_qty/item_reason/attachments صور حتى 5 × 5MB).
434: - الأدمن (صلاحيات returns.view/create/update/delete — إجراءات approve/receive/refund تحت returns.update): ‏CRUD ‏`/api/v1/admin/returns` بفلاتر status/order_id/customer_id/search (برقم المرتجع أو رقم الطلب)، و`POST /api/v1/admin/returns/{id}/approve|receive|refund`، وإنشاء يدوي من نفس store لخدمة العملاء.
435: 
436: ## المرحلة 10: المشتريات والموردين ومتوسط التكلفة وبوابة المورد
437: 
438: ### النموذج والمحاسبة
439: 
440: - الجداول: ‏`suppliers` ‏(code فريد، أجل سداد، رصيد افتتاحي/جاري) — و`supplier_users.supplier_id` بقى Foreign Key فعليًا (nullOnDelete) — `purchase_requests`/`purchase_request_items` ‏(طلبات نواقص الفروع)، `purchase_orders`/`purchase_order_items` ‏(مرقمة PO- من SettingService)، `supplier_deliveries`/`supplier_delivery_items` ‏(إشعارات توريد ASN مرقمة DLV-)، `supplier_invoices` ‏(داخلي SIN- + رقم ورقي) و`supplier_payments` ‏(SPY-). ترقيمات PR-/DLV-/SIN-/SPY- أضيفت لـ SettingService/SettingSeeder (تبدأ 1001، حشو 6).
441: - **متوسط التكلفة المرجح (WAC)** عند الاستلام: ‏`NewAvg = (مجموع on_hand في كل الفروع × التكلفة الحالية + المستلم × سعر الشراء) ÷ (المجموع + المستلم)` — يحدّث `product_variants.cost_price` (بدقة عموده decimal(12,2)) و`last_cost_price` (decimal(12,4) جديد) بسعر الشراء الفعلي، ثم حركة `purchase_receipt` عبر InventoryService بمرجع morph ‏`purchase_order` على فرع الاستلام.
442: - **دفتر المورد الدائن**: الرصيد الجاري يبدأ من الافتتاحي؛ اعتماد فاتورة (post) يزيده بقيمة الإجمالي، والدفعة تنقصه وتحدّث paid_amount/حالة فاتورتها (posted ← partially_paid ← paid). حذف دفعة أو إلغاء فاتورة معتمدة غير مسددة يعكس الأثر كاملًا. أرقام الفاتورة/الدفعة والترتيب كله محكوم بقفل صف المورد/الفاتورة داخل معاملات.
443: 
444: ### إدارة المشتريات — ‏`/api/v1/admin` (صلاحيات suppliers.* وpurchases.*)
445: 
446: - ‏CRUD ‏`/suppliers` ‏(بحث name/code/company + is_active) — الحذف ممنوع 422 عند وجود أوامر/فواتير/دفعات/حسابات. حسابات موظفي المورد: ‏`GET|POST /suppliers/{id}/users` و`PUT|DELETE /suppliers/{id}/users/{user}`.
447: - ‏CRUD ‏`/purchase-requests` + إجراءات `POST /{id}/submit|approve|reject` — الدورة draft ← pending ← approved/rejected؛ التعديل والحذف للمسودة فقط.
448: - ‏CRUD ‏`/purchase-orders` + `POST /{id}/approve` ‏(ختم approved_by على المسودة) و`/{id}/send` ‏(draft أو change_requested ← sent_to_supplier) و`/{id}/cancel` ‏(قبل أي استلام) و`/{id}/receive` ‏(قلب المرحلة: items [{purchase_order_item_id, qty}] + location_id اختياري + supplier_delivery_id اختياري لمطابقة إشعار توريد وتحديث حالته). إنشاء مربوط بـ purchase_request_id معتمد ينسخ بنوده (بسعر التكلفة الحالية) ويحوّل الطلب لـ converted_to_po. الإجماليات خادمية: line_total = qty × cost، والضريبة من tax_rate لكل بند، والنهائي = subtotal − discount + tax. الاستلام متاح من sent_to_supplier/supplier_accepted/partially_received فقط، والمستلم التراكمي ≤ المطلوب، والحالة تنتهي completed أو partially_received.
449: - ‏CRUD ‏`/supplier-invoices` + `POST /{id}/post|cancel` — الإجمالي = subtotal + tax (خادمي)، والاستحقاق الافتراضي = الإصدار + payment_terms_days للمورد عند غياب due_date، ومرفق attachment ‏(pdf/صور ≤ 10MB) على القرص المحلي، والتعديل للمسودة فقط.
450: - ‏CRUD ‏`/supplier-payments` — الربط بفاتورة اختياري (نفس المورد، معتمدة/جزئية، وبسقف متبقيها)؛ تعديل الحقول غير المالية فقط، والحذف يعكس الرصيد والفاتورة.
451: 
452: ### بوابة المورد — ‏`/api/v1/supplier` ‏(supplier_users + Sanctum)
453: 
454: - ‏`POST /auth/login` ‏(throttle 10/دقيقة): حساب نشط + مورد نشط ← توكن `supplier-token`. ‏`POST /auth/logout`.
455: - ‏`GET /dashboard`: عدد الجاهز للموافقة (sent_to_supplier)، وقيد التوريد (supplier_accepted/partially_received)، والرصيد المستحق الحالي، وآخر 5 دفعات.
456: - ‏`GET /purchase-orders` و`GET /purchase-orders/{id}` — **مقيدة كلها بـ supplier_id صاحب التوكن** (أمر مورد آخر = 404). ‏`POST /purchase-orders/{id}/accept` ‏(sent ← accepted)، و`POST /purchase-orders/{id}/request-change` ‏(notes إلزامية ← change_requested + supplier_change_notes تنبيهًا لمدير المشتريات؛ تعالجها الإدارة بتعديل المسودة/إعادة الإرسال).
457: - ‏`POST /purchase-orders/{id}/deliveries` ‏(ASN): items [{purchase_order_item_id, shipped_qty}] + delivery_date + supplier_invoice_no + invoice_file ‏(pdf/صور ≤ 10MB). سقف الشحن التراكمي لكل بند (عدا المرفوضة) = المطلوب؛ والحالات المسموحة sent/accepted/partially_received — والشحن من sent يعد قبولًا ضمنيًا فيحوّلها accepted. عرضها: ‏`GET /deliveries` و`GET /deliveries/{id}` (بنطاق المورد).
458: - ‏`GET /statement?from_date&to_date`: كشف حساب دفتري — رصيد افتتاحي محسوب من كل ما قبل الفترة (افتتاحي المورد + فواتير معتمدة − دفعات)، ثم حركات الفترة (فاتورة = credit، دفعة = debit) بترتيب التاريخ (الفاتورة قبل الدفعة في اليوم نفسه) مع running_balance بعد كل حركة وإجماليات ورصيد ختامي يطابق current_balance عند اكتمال الفترة لليوم.
459: 
460: ## جولة إغلاق تدقيق المرحلتين 9–10 (task.txt)
461: 
462: مراجعة تحقق بندًا ببند لتدقيق المرتجعات والمشتريات والمحفظة مقابل الكود: أغلب البنود وُجدت مُصلَحة ومختبَرة في جولة التقوية السابقة (تسلسلات أرقام المستندات `document_next_number` بدل قفل صف الإعدادات H2، إلغاء دفعات المورد void بدل الحذف وتجميد الرصيد الافتتاحي وتاريخ الدفعة H4، رد المرتجع مشروط بطلب مدفوع مع شمول ضريبة البند والمقارنة بالمبلغ القابل للرد وحالة partially_refunded ‏H1/H3، فرض الرد للمحفظة للطلبات المدفوعة بها M9، قيود CHECK المالية والكمية M11، بصمة عدم تكرار موحّدة وتنظيف مجدول للمفاتيح L1، حدود دخول المورد بالبريد والـ IP وتوكنات بسقف وانتهاء L2، المحفظة من الإعدادات فقط L3، حظر الاعتماد الذاتي للمشتريات وصلاحية purchase_requests.approve ‏M5، wallet_balance خارج الإسناد الجماعي M6، مطابقة فواتير المورد بسقف إجمالي الأمر وتخصيص الدفعات غير المرتبطة M7، return_window_days=0 تعني إيقاف الإرجاع M8، سقف مرفقات المرتجع 10 ملفات/25MB ‏M2). أُكملت في هذه الجولة ثلاث فجوات متبقية:
463: 
464: - **L4**: استلام أمر الشراء يعيد فحص نشاط فرع الاستلام لحظة الاستلام الفعلي (كان يُفحص عند الإنشاء/التعديل فقط)، فيُرفض الاستلام لفرع عُطّل بعد إرسال الأمر بلا أي حركة مخزون.
465: - **L5**: تجميعات المرتجعات السابقة في استلام المرتجع تُحسب باستعلام واحد مجمّع (`GROUP BY order_item_id`) بدل استعلام لكل بند.
466: - **L6**: فهرس `supplier_payments (supplier_id, payment_date)` لاستعلامات كشف الحساب، بهجرة `CREATE INDEX CONCURRENTLY` خارج المعاملة.
467: - تصحيحات اختبارات بأقل تغيير لتوافق سلوك التدقيق نفسه: الاعتماد في اختبارات المشتريات يتم بمدير غير المنشئ (M5)، وطلبات اختبارات التقوية مُسلّمة مدفوعة كما في التدفق الحقيقي (H1)، واختبار الرصيد الافتتاحي يثبّت تجميده بعد الحركات (H4).
468: 
469: ## المرحلة 12: بوابة الجملة المتقدمة (B2B) — 12.1 عروض الأسعار وإشعارات السداد
470: 
471: متطلبات تأسيسية: حزمتا `maatwebsite/excel` (^4.0) و`barryvdh/laravel-dompdf` (^3.1) مثبّتتان لمهام التصدير القادمة. قاعدة حماية المرحلة: كل مسارات `/api/v1/wholesale` الجديدة تحت الميدل وير الثلاثي `['auth:sanctum', 'auth.customer', 'wholesale.approved']` — العميل القطاعي أو التاجر قيد المراجعة يُمنع (403)، والزائر 401.
472: 
473: ### عروض الأسعار — `/api/v1/wholesale/quotations` (تاجر) + `/api/v1/admin/quotations` (إدارة)
474: 
475: - التاجر: `GET/POST /quotations`، `GET/PUT/DELETE /quotations/{id}` (الحذف والتعديل للمسودة فقط)، و`POST /quotations/{id}/submit|accept|reject`. الإنشاء ببنود [{product_variant_id, qty, requested_target_price?}] — السعر المعروض الابتدائي يُحسب من `PricingService` حسب التاجر والكمية وشرائح الأسعار، ورقم العرض من ترقيم `quotation` ‏(QT-). الإجماليات خادمية: line_total = العرض × الكمية، والنهائي = subtotal − discount + tax.
476: - دورة الحياة: draft ← requested (إرسال التاجر) ← priced_by_admin (تسعير الإدارة) ← accepted / rejected، أو expired. القبول بعد تجاوز valid_until يُرفض ويحوّل العرض إلى expired تلقائيًا. الحالة converted_to_order محفوظة بخطوة التحويل لطلب (مهمة لاحقة) مع عمود converted_order_id للتتبع.
477: - الإدارة (صلاحيات quotations.view / quotations.price): `GET /quotations` (فلترة بالحالة/العميل) و`GET /quotations/{id}` و`POST /quotations/{id}/price` ‏(بنود [{id, offered_unit_price}] اختيارية + discount_amount + tax_amount + valid_until + admin_notes ← priced_by_admin) و`POST /quotations/{id}/expire`.
478: 
479: ### إشعارات السداد البنكي — `/api/v1/wholesale/payment-notices` + `/api/v1/admin/payment-notices`
480: 
481: - التاجر: `POST /payment-notices` ‏(amount, payment_method ‏[bank_transfer|check|deposit], bank_name, reference_number, transfer_date, order_id اختياري, receipt ‏[صورة/pdf ≤ 10MB على القرص الخاص]) و`GET /payment-notices` و`GET /payment-notices/{id}` (نطاق ملكيته فقط، وطلب الغير = 404) و`GET /payment-notices/outstanding` ‏(المديونية الآجلة الحالية + حد الائتمان) و`GET /payment-notices/{id}/receipt` لتنزيل إيصاله.
482: - رقم الإشعار من نوع ترقيم جديد `payment_notice` ‏(WPN-001001). إشعار مرتبط بطلب: الطلب يجب أن يكون آجلًا (credit) غير مسدد وغير ملغي لنفس التاجر، ومجموع المعتمد + قيد المراجعة عليه لا يتجاوز إجماليه.
483: - المديونية الآجلة = مجموع طلبات الآجل غير المسددة غير الملغاة − مجموع الإشعارات المعتمدة (الحرّة أو المرتبطة بطلب ما زال غير مسدد). عند اعتماد الإدارة (payment_notices.approve): يُرفض أي مبلغ أكبر من المديونية الحالية، وتُسجَّل حركة قبض `customer_receipt` عبر TreasuryService في الخزينة الممرّرة treasury_id أو الافتراضية (أول بنكية نشطة، وإلا أول رئيسية نشطة) بمرجع morph ‏`wholesale_payment_notice`، ويُختم الإشعار بـ treasury_id + treasury_transaction_id + reviewed_by؛ وإذا غطّت الإشعارات المعتمدة الطلب المرتبط بالكامل تحوّل إلى paid وخرج هو وإشعاراته من المعادلة معًا (لا خصم مزدوج). الرفض بـ payment_notices.reject، والمراجعة الثانية على نفس الإشعار مرفوضة 422.
484: - الإدارة: `GET /payment-notices` و`GET /payment-notices/{id}` ‏(payment_notices.view) و`POST /payment-notices/{id}/approve|reject` و`GET /payment-notices/{id}/receipt` لتنزيل الإيصال.
485: 
486: ### متحكمات بوابة الجملة (المرحلة 12.2) — كلها تحت الحماية الثلاثية
487: 
488: - `GET /dashboard`: الحد الائتماني credit_limit، والمسحوب used_credit (= المديونية الآجلة من معادلة 12.1)، والمتاح للشراء الآجل (limit − used)، وعدد الطلبات قيد التنفيذ (pending/confirmed/processing/shipped)، وآخر 5 فواتير وآخر 5 عروض أسعار.
489: - `GET /products`: كتالوج المنتجات المنشورة — لكل متغير نشط: your_price بسعر PricingService عند كمية 1، وtier_prices سلم الشرائح الساري لهذا التاجر (نقاط min_qty من قائمه المؤهلة وسعر كل شريحة = resolve عند حدّها، فالسلم مطابق للتحصيل الفعلي)، وavailable_qty (مجموع المتاح بكل الفروع). متغير غير مُسعَّر يظهر بسعر null بدل إسقاط الصفحة.
490: - `GET /price-list/export?format=xlsx|pdf`: الـ xlsx عبر Maatwebsite Excel ‏(WholesalePriceListExport: ‏SKU, Barcode, Product Name, Base Price, Your Wholesale Price, Quantity Tiers) والـ PDF عبر DomPDF ‏(قالب pdfs.wholesale_price_list بترويسة الشركة واسم التاجر وصلاحية 30 يومًا) — والصفوف من WholesalePriceListService كمصدر موحّد للصيغتين.
491: - `POST /quick-order/lookup`: بنود [{sku|barcode, qty}] حتى 500 — لكل بند: وُجد أم لا، سعر شريحته عند كميته، line_total، المتاح، in_stock، وسلّم شرائحه.
492: - `POST /quick-order/import`: ملف xlsx/xls/csv بعمودين (sku, qty) يُقرأ بـ Maatwebsite ‏(WholesaleQuickOrderImport) — الأكواد المكررة تُدمج أولًا، وغير المعروف/غير النشط يُتخطى بـ not_found_or_inactive، وما لا يغطيه المتاح (شاملًا ما في السلة) بـ insufficient_stock، والباقي يُضاف لسلة التاجر عبر CartService بأسعار اليوم، مع تقرير added/skipped والسلة الناتجة.
493: - `POST /orders/{order}/reorder`: نسخ بنود طلب سابق للتاجر (طلب الغير = 404) إلى سلته الحالية بنفس منطق الاستيراد — إعادة التسعير تلقائية عبر CartService/PricingService بأسعار اليوم لا أسعار الطلب القديم.
494: - `GET /invoices`: فواتير التاجر = طلباته الآجلة والمسددة (فلترة payment_status) مع pdf_url لكل فاتورة، و`GET /invoices/{order}/pdf` تنزيل فاتورة PDF ‏(قالب pdfs.wholesale_invoice؛ طلب الغير = 404).
495: - `GET /statement?from&to`: كشف حساب من WholesalePaymentNoticeService — طلبات آجلة غير ملغاة Debit بتاريخ إنشائها، وإشعارات معتمدة Credit بتاريخ اعتمادها، ومرتجعات مستردة (refunded) Credit بمبلغ total_refund_amount، بترتيب (المدين قبل الدائن في اليوم نفسه) ورصيد تراكمي يبدأ من رصيد افتتاحي محسوب لما قبل الفترة.
496: - قبول عرض السعر (من 12.1) أصبح يحوّله تلقائيًا إلى طلب مؤكد: قبول العرض المسعّر ينشئ طلبًا بقناة wholesale وطريقة credit غير مسدد بأسعار العرض الثابتة (خصم/ضريبة الترويسة موزّعان على البنود بأكبر باقٍ)، ويحجز مخزونه عبر OrderAllocationService، ويؤكّده عبر OrderService::changeStatus — نقص المخزون يُسقط التحويل ويبقى العرض مسعّرًا، وحالة العرض النهائية converted_to_order مع converted_order_id.
497: 
498: ## المرحلة 13: الإشعارات الموحدة والطوابير والتقارير
499: 
500: ### 13.1 الأحداث والإشعارات (كل المستمعين والإشعارات ShouldQueue، والقناة database فقط)
501: 
502: - جدول `notifications` القياسي (`php artisan notifications:table`) بعلاقة polymorphic — يعمل مع users وcustomers وsupplier_users (الثلاثة Notifiable أصلًا). المستمعون يُكتشفون تلقائيًا من app/Listeners.
503: - `OrderCreated` (من OrderService::createFromCart ومن تحويل عروض أسعار الجملة) ← OrderConfirmationNotification للعميل + AdminOrderCreatedNotification لطاقم الإدارة (حاملو orders.view ودور Super Admin عبر StaffRecipients).
504: - `StockLowDetected` يُطلق من داخل InventoryService::recordMovement عند عبور المتاح حد إعادة الطلب الفعّال نزولًا فقط (حد صف الرصيد وإلا حد المتغير؛ قراءة حد المتغير باستعلام مباشر لأن علاقة variant محمّلة جزئيًا من lockLevels) ← LowStockAlertNotification لمديري المشتريات (purchases.view) ومديري الفرع (مقيدون بالفرع + inventory.view).
505: - `TransferPendingApproval` (عند إنشاء التحويلة في TransferService) ← حاملو transfers.approve. و`WholesaleApplicationSubmitted` (داخل WholesaleRegistrationService) ← حاملو customers.approve، و`WholesaleApplicationReviewed` (من اعتماد/رفض CustomerManagementService لغير القطاعي) ← التاجر نفسه بالنتيجة والسبب. و`PurchaseOrderSentToSupplier` (من ProcurementService::sendPurchaseOrder) ← مستخدمو المورد النشطون.
506: - متحكم موحد `Shared\NotificationController` في البوابات الخمس بنفس المسارين: `GET .../notifications` (ترقيم 20 + meta.unread_count) و`POST .../notifications/{id}/read` (إشعار الغير = 404): في admin وsupplier وwholesale وpos على جذر البوابة، وفي المتجر داخل مجموعة auth ‏(/store/auth/notifications).
507: 
508: ### 13.2 التقارير ولوحة المعلومات (إدارة، بصلاحية reports.view)
509: 
510: قاعدة الأداء مطبقة حرفيًا: كل الأرقام من استعلامات تجميعية (SUM/COUNT/GROUP BY/CASE WHEN) في ReportService — لا جلب سجلات وحساب في PHP — وهجرة فهارس للباقي (supplier_invoices ‏(supplier_id,status) وdue_date، وstock_movements ‏(type,created_at)؛ الطلبات مغطاة أصلًا). «طلبات المبيعات» في كل التقارير = حالات confirmed/processing/shipped/delivered فقط.
511: 
512: - `GET /admin/dashboard`: مبيعات اليوم والشهر مقسمة بالقنوات (store/wholesale/pos)، عدد طلبات اليوم الجديدة، low_stock_count (بالحد الفعّال)، طلبات الجملة المعلّقة، وأفضل 5 منتجات وأفضل 5 فروع مبيعًا هذا الشهر.
513: - `GET /admin/reports/sales?from&to&granularity=daily|monthly&group_by=branch|channel|cashier|payment_method`: صفوف فترات بإجمالي/خصومات/ضرائب/شحن/صافٍ + صف totals. الكاشير = مستخدم وردية POS المرتبطة بالطلب.
514: - `GET /admin/reports/inventory?dead_days=90`: تقييم كل فرع = ‏Σ(on_hand × cost_price) + الإجمالي، والأصناف الراكدة (رصيد > 0 وآخر حركة أقدم من X يوم أو بلا حركات) بقيمتها المحبوسة.
515: - `GET /admin/reports/profit?from&to`: صافي إيراد المبيعات − COGS (من حركات sale في الدفتر: ‏Σ(|qty| × unit_cost المسجل أو cost_price الحالي عند غيابه)) = مجمل الربح، − مصروفات الفترة (حسب expense_date) = صافي الربح.
516: - `GET /admin/reports/suppliers`: لكل مورد: الرصيد الحالي، إجمالي المشتريات (فواتير posted/partially_paid/paid)، وأعمار المستحق غير المسدد (غير مستحق/1–30/31–60/61–90/+90 يوم تأخير حسب due_date).
517: - `GET /admin/reports/shifts?from&to&only_differences=1`: ورديات POS بأرقامها المسجلة (نقدي/شبكة/مرتجعات/مصروفات/متوقع/فعلي/فرق) مع has_difference وإجماليات، والفلتر يركز على ذوات الفروق.
518: 
519: ### تجميع ملفات الروابط النهائية (pos / wholesale / admin)
520: 
521: - ملف pos.php أُعيد تنظيمه على أقسام (مصادقة، ورديات، منتجات ومبيعات، مخزون وتحويلات وجرد، إشعارات) بجدول مسارات مطابق تمامًا لما قبله (تحقق بـ route:list diff): المتحكمات الفعلية بأسماء PosAuthController/PosShiftController/PosSaleController/PosProductController/PosStockController (طلبات التحويل والاستلام ومسح الجرد طرق في PosStockController)، وحمايات قائمة لم تُمس: throttle على دخول الكاشير، وفصل مسارات الوردية المفتوحة (pos.shift) عن مسارات التوكن فقط، وأنماط المعرّفات الرقمية، وauth/logout.
522: - في wholesale.php: إنشاء إشعار السداد `POST payment-notices` انتقل إلى InvoiceController@storePaymentNotice (بنفس StorePaymentNoticeRequest والخدمة والـ Resource — المسار والاسم والسلوك لم يتغيروا)، وبقية إشعارات السداد (قائمة/عرض/مديونية/إيصال) في PaymentNoticeController. وتبقى إضافات موثقة فوق الجدول الأساسي: quotations/{id}/submit، وinvoices/{order}/pdf.
523: - في admin.php: إضافات المرحلتين 11 و13 موجودة أصلًا بجدول مطابق (apiResource للخزائن/المصروفات/تحويلات الخزائن، وshifts/{shift}/approve عبر PosShiftAdminController، وdashboard وreports بصلاحية reports.view، والإشعارات) فلم يُعَد فتح الملف.
